import type { BankQuestion } from "@/lib/bank";

/** Operations, Supply Chain & Business Analytics (Management & Commerce): 248 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-operations-analytics-1","question":"A bottling unit has a design capacity of 500 crates per day and an effective capacity of 400 crates per day. Last week it averaged 340 crates per day. What was its efficiency?","options":["85%","117.6%","80%","68%"],"answer":0,"explanation":"Efficiency = actual output ÷ effective capacity = 340 ÷ 400 = 85%. Utilisation uses design capacity instead: 340 ÷ 500 = 68%.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-2","question":"Customers arrive at a pharmacy at an average rate of 40 per hour and spend an average of 15 minutes inside. On average, how many customers are inside the pharmacy at any moment?","options":["25","2.67","600","10"],"answer":3,"explanation":"Little's law: L = λ × W = 40 per hour × (15/60) hour = 10. Multiplying 40 by 15 without converting minutes to hours gives 600.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-3","question":"A plant runs one 7.5-hour shift with 30 minutes of breaks. Daily customer demand is 840 units. What is the takt time?","options":["45 seconds","30 seconds","32.1 seconds","2 minutes"],"answer":1,"explanation":"Available time = 450 − 30 = 420 minutes = 25,200 s. Takt = available time ÷ demand = 25,200 ÷ 840 = 30 s. Forgetting the breaks gives 27,000 ÷ 840 ≈ 32.1 s.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-4","question":"A three-stage process: Stage 1 has one machine taking 6 min per unit; Stage 2 has two identical machines in parallel, each taking 15 min per unit; Stage 3 has one machine taking 5 min per unit. What is the maximum output in an 8-hour shift?","options":["80","32","64","96"],"answer":2,"explanation":"Capacities per hour: Stage 1 = 60/6 = 10, Stage 2 = 2 × 60/15 = 8, Stage 3 = 60/5 = 12. The bottleneck is Stage 2 at 8 units/hour, so output = 8 × 8 = 64. Ignoring the parallel machine gives 4 × 8 = 32.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-5","question":"A distribution centre holds an average of 6,000 units and ships 1,200 units per week. Assuming 52 weeks a year, what is its annual inventory turnover?","options":["10.4","5","20.8","0.2"],"answer":0,"explanation":"Little's law: average time in stock W = I ÷ throughput = 6,000 ÷ 1,200 = 5 weeks. Turns per year = 52 ÷ 5 = 10.4. 5 is the flow time in weeks, not the turnover.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-6","question":"An assembly line must produce 1,600 units in 480 productive minutes per day. The six tasks take 10, 12, 8, 15, 7 and 9 seconds. What is the theoretical minimum number of workstations?","options":["3","5","4","6"],"answer":2,"explanation":"Takt (cycle) time = 480 × 60 ÷ 1,600 = 18 s. Work content = 61 s. Minimum stations = ⌈61 ÷ 18⌉ = ⌈3.39⌉ = 4. Rounding down to 3 is the classic error: stations must be rounded up.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-7","question":"For the same line (work content 61 s, cycle time 18 s), precedence constraints force the planner to use 5 stations. What is the balance delay?","options":["18.7%","32.2%","15.3%","67.8%"],"answer":1,"explanation":"Efficiency = work content ÷ (stations × cycle time) = 61 ÷ (5 × 18) = 67.8%. Balance delay = 1 − efficiency = 32.2%. 15.3% is the delay with 4 stations; 18.7% wrongly uses the longest task (15 s) as cycle time.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-8","question":"A loan-processing centre receives 120 applications per week and has on average 360 applications in process. Management wants the average processing time cut to 1.5 weeks without changing the arrival rate. By how many applications must average work-in-process fall?","options":["120","240","90","180"],"answer":3,"explanation":"Current W = 360 ÷ 120 = 3 weeks. Target WIP = 120 × 1.5 = 180. Reduction = 360 − 180 = 180 applications.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-9","question":"A serial line has three stages. Stage 1: capacity 100 units/hr, yield 95%. Stage 2: capacity 90 units/hr, yield 90%. Stage 3: capacity 85 units/hr, yield 98%. Defective units are scrapped immediately after each stage. What is the maximum rate of good finished output?","options":["85.00 units/hr","75.41 units/hr","79.38 units/hr","83.30 units/hr"],"answer":2,"explanation":"Let x enter Stage 1. Stage 2 sees 0.95x ≤ 90 → x ≤ 94.74. Stage 3 sees 0.855x ≤ 85 → x ≤ 99.42. Stage 1 allows x ≤ 100. So x = 94.74 (Stage 2 binds) and good output = 90 × 0.90 × 0.98 = 79.38/hr. Applying the Stage-1 yield again to the bottleneck capacity gives 75.41.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-10","question":"A single-server help desk (M/M/1) receives 12 requests per hour and can serve 15 per hour. What is the average time a request waits in the queue before service starts?","options":["3.2 minutes","16 minutes","20 minutes","4 minutes"],"answer":1,"explanation":"ρ = 12/15 = 0.8. Lq = ρ²/(1 − ρ) = 0.64/0.2 = 3.2. Wq = Lq/λ = 3.2/12 hr = 16 min. 20 min is W (time in system) = 1/(μ − λ); 4 min is the service time alone.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-11","question":"A single-window ticket counter (M/M/1) has an arrival rate of 18 per hour and a service rate of 24 per hour. What is the probability that the counter is idle?","options":["0.25","0.75","0.33","0.43"],"answer":0,"explanation":"ρ = λ/μ = 18/24 = 0.75, the probability the server is busy. P(idle) = P0 = 1 − ρ = 0.25.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-12","question":"Customers arrive at a single drive-through window at 20 per hour (M/M/1). Management wants the average wait in the queue (before ordering) to be at most 6 minutes. What is the smallest whole-number service rate per hour that achieves this?","options":["30","25","27","28"],"answer":3,"explanation":"Wq = λ / [μ(μ − λ)] ≤ 0.1 hr → 20 ≤ 0.1μ(μ − 20) → μ² − 20μ − 200 ≥ 0 → μ ≥ 10 + √300 ≈ 27.32. So μ = 28. μ = 27 gives Wq = 20/(27×7) hr ≈ 6.35 min, too long. 30 is what you get by limiting time in system W = 1/(μ − λ) instead of the queue wait.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-13","question":"A diagnostic clinic sees 30 patients per hour. Every patient passes registration (on average 4 patients there) and a doctor (on average 6 patients), and 60% also visit the lab, where on average 9 patients are present. What is the average time spent in the lab by a patient who visits it?","options":["38 minutes","30 minutes","18 minutes","15 minutes"],"answer":1,"explanation":"Apply Little's law to the lab alone. Flow into the lab = 0.6 × 30 = 18 patients/hr, so W = 9 ÷ 18 hr = 30 min. Dividing by all 30 patients gives 18 min; 38 min is the average time in the whole clinic, (4 + 9 + 6) ÷ 30 hr.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-14","question":"A machine is available for 480 minutes a day. Product A needs 4 minutes and product B 6 minutes on it. Daily demand is 50 units of A and 40 of B. What is the machine's utilisation?","options":["91.7%","87.5%","108.3%","100.0%"],"answer":0,"explanation":"Load = 50 × 4 + 40 × 6 = 200 + 240 = 440 min. Utilisation = 440 ÷ 480 = 91.7%.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-15","question":"Expected monthly demand for a service is 9,000 jobs. The firm wants a capacity cushion of 20% (measured as a share of capacity). What capacity should it plan?","options":["9,200 jobs","10,800 jobs","7,200 jobs","11,250 jobs"],"answer":3,"explanation":"Capacity cushion = 1 − utilisation, so demand = 80% of capacity. Capacity = 9,000 ÷ 0.8 = 11,250. Adding 20% of demand (10,800) understates it, because the cushion is measured against capacity.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-16","question":"Annual demand is 66,000 good units. Each unit needs 12 minutes of machine time. Plants run 250 days a year, 2 shifts of 8 hours, with 85% machine efficiency, and 4% of units started are scrapped. How many machines are needed?","options":["3","4","5","6"],"answer":2,"explanation":"Units to start = 66,000 ÷ 0.96 = 68,750. Hours needed = 68,750 × 12/60 = 13,750. Effective hours per machine = 250 × 2 × 8 × 0.85 = 3,400. Machines = 13,750 ÷ 3,400 = 4.04 → 5. Ignoring scrap gives 13,200 ÷ 3,400 = 3.88 → 4.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-17","question":"A unit's design capacity is 200 units/day. Its utilisation is 75% and its efficiency is 90%. What is its effective capacity (approximately)?","options":["150 units/day","135 units/day","180 units/day","167 units/day"],"answer":3,"explanation":"Actual output = utilisation × design = 0.75 × 200 = 150. Efficiency = actual ÷ effective → effective = 150 ÷ 0.9 ≈ 166.7 ≈ 167 units/day. 150 is the actual output; 135 multiplies both percentages.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-18","question":"Assertion (A): Adding capacity at a non-bottleneck station does not increase the throughput of a serial process.\nReason (R): The throughput of a serial process is set by its slowest resource.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: output is capped by the bottleneck, so extra capacity anywhere else only adds idle time.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-19","question":"Which statements about Little's law (L = λW) are correct?\nI. It holds in steady state whatever the arrival and service-time distributions.\nII. It holds only for first-come-first-served queues.\nIII. It can be applied to any boundary drawn around part of a system.\nIV. λ is the average throughput rate across the boundary.","options":["I and II only","I, III and IV only","I, II, III and IV","II, III and IV only"],"answer":1,"explanation":"Little's law needs only a stable (steady-state) system; it is independent of distributions and of the queue discipline, so II is false. It applies to any subsystem, with λ the flow rate through that boundary.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-20","question":"A plant works 5 days a week, 2 shifts a day. Each 8-hour shift has two 15-minute tea breaks and a 30-minute lunch. Weekly demand is 1,350 units. What is the takt time?","options":["93.3 seconds","200.0 seconds","186.7 seconds","213.3 seconds"],"answer":2,"explanation":"Available per shift = 480 − 60 = 420 min. Weekly = 420 × 2 × 5 = 4200 min. Takt = 4200 ÷ 1,350 = 3.1111 min = 186.7 s. Deducting only lunch gives 4,500/1,350 min = 200 s; ignoring all breaks gives 213.3 s.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-21","question":"Tasks (time in s; immediate predecessors): A 8 (–), B 5 (A), C 6 (A), D 9 (B), E 4 (C), F 7 (D, E), G 3 (F). The cycle time is 12 s. Tasks are assigned to stations using the 'longest eligible task first' rule. What is the efficiency of the resulting line?","options":["70.0%","30.0%","76.4%","87.5%"],"answer":0,"explanation":"Assignment: S1 {A} = 8; S2 {C, B} = 11; S3 {D} = 9 (E no longer fits); S4 {E, F} = 11; S5 {G} = 3. Five stations, so efficiency = 42 ÷ (5 × 12) = 70%. 87.5% assumes the theoretical minimum of ⌈42/12⌉ = 4 stations; 76.4% uses the largest station load (11 s) instead of the cycle time.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-22","question":"A machine needs a 60-minute setup before each batch and then 2 minutes per unit. Downstream demand is 27 units per hour. What is the smallest batch size that lets this machine keep up with demand?","options":["135","243","270","30"],"answer":2,"explanation":"Capacity with batch B = B ÷ (60 + 2B) units per minute. Set it equal to 27/60 = 0.45: B = 0.45(60 + 2B) = 27 + 0.9B → 0.1B = 27 → B = 270. Note that even an infinite batch cannot exceed 30 units/hr (1 per 2 min).","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-23","question":"A process has a throughput of 50 units per hour and a flow time of 3 hours. If a WIP cap reduces average work-in-process to 100 units while throughput stays the same, what is the new flow time?","options":["3 hours","4.5 hours","1.5 hours","2 hours"],"answer":3,"explanation":"Current WIP = 50 × 3 = 150. With WIP = 100 and λ = 50, W = 100 ÷ 50 = 2 hours.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-24","question":"A distributor has annual sales of ₹64 crore, cost of goods sold of ₹48 crore and an average inventory (at cost) of ₹6 crore. Using a 365-day year, how many days of inventory does it hold?","options":["34.2 days","45.6 days","8.0 days","12.0 days"],"answer":1,"explanation":"Inventory turnover = COGS ÷ average inventory = 48 ÷ 6 = 8. Days of inventory = 365 ÷ 8 = 45.6. Using sales (64 ÷ 6) mixes a selling-price numerator with a cost denominator and gives 34.2 days.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-25","question":"Products P and Q share two machines, each available 480 min/day. P needs 3 min on M1 and 4 min on M2; Q needs 5 min on M1 and 2 min on M2. Current daily demand is 60 P and 40 Q. By what maximum percentage can both demands be increased in the same proportion?","options":["20.8%","50.0%","26.3%","33.3%"],"answer":2,"explanation":"M1 load = 60×3 + 40×5 = 380 min; M2 load = 60×4 + 40×2 = 320 min. M1 binds: scale ≤ 480/380 = 1.2632, i.e. an increase of 26.3%. 50% is M2's headroom; 20.8% is M1's idle share of 480, not the headroom relative to the load.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-26","question":"Station A takes 10 min per unit and Station B takes 12 min per unit. After Station B, 20% of units fail inspection and go back through Station B once (rework takes the full 12 minutes and always succeeds). What is the line's output in an 8-hour shift?","options":["48.0 units","33.3 units","40.0 units","32.0 units"],"answer":1,"explanation":"Each good unit needs 1.2 passes at B: 1.2 × 12 = 14.4 min. B's capacity = 60/14.4 = 4.167 units/hr (A: 6/hr), so B is the bottleneck. Output = 4.167 × 8 = 33.3 units. 40 ignores rework; 32 treats the 20% as scrap.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-27","question":"A retailer sells ₹30 lakh a month at a 25% gross margin (on sales) and carries an average inventory of ₹45 lakh at cost. Holding cost is 24% a year of inventory value. If inventory days (30-day month) are cut to 40 days at the same sales, what is the annual saving in holding cost?","options":["₹4.8 lakh","₹1.2 lakh","₹15 lakh","₹3.6 lakh"],"answer":3,"explanation":"COGS = 0.75 × 30 = ₹22.5 lakh/month = ₹0.75 lakh/day. Current days = 45 ÷ 0.75 = 60. At 40 days inventory = 40 × 0.75 = ₹30 lakh, freeing ₹15 lakh. Saving = 15 × 0.24 = ₹3.6 lakh. Using sales instead of COGS gives 45 days now, ₹40 lakh at 40 days and only ₹1.2 lakh saved.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-28","question":"Jobs arrive at 10 per hour (M/M/1). Option A: a server who handles 12 jobs/hr, costing ₹200/hr. Option B: a server who handles 15 jobs/hr, costing ₹300/hr. Each job in the system (waiting or in service) costs ₹100 per hour. Which option is cheaper, and what is its total hourly cost?","options":["Option B, ₹500/hr","Option A, ₹617/hr","Option B, ₹433/hr","Option A, ₹700/hr"],"answer":0,"explanation":"L = λ/(μ − λ). A: L = 10/2 = 5 → 200 + 500 = ₹700. B: L = 10/5 = 2 → 300 + 200 = ₹500. B is cheaper. Using Lq (queue only) instead of L gives ₹433 for B, but the cost is charged on every job in the system.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-29","question":"In the Theory of Constraints, which scheduling method paces the whole plant to the bottleneck, protects it with a time buffer and releases material in step with it?","options":["Economic Order Quantity","Kanban","Drum–Buffer–Rope","Material Requirements Planning"],"answer":2,"explanation":"In Drum–Buffer–Rope the bottleneck is the drum that sets the pace, the buffer protects it from upstream disruptions, and the rope ties material release to the drum's rate.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-30","question":"Planned production time is 480 minutes, of which 60 minutes are lost to breakdowns. The ideal cycle time is 0.5 min/unit. The machine produced 700 units, of which 665 were good. What is the OEE?","options":["72.9%","79.2%","83.1%","69.3%"],"answer":3,"explanation":"Availability = 420/480 = 0.875. Performance = (700 × 0.5)/420 = 0.8333. Quality = 665/700 = 0.95. OEE = A × P × Q = 69.3% (check: 665 × 0.5 ÷ 480 = 0.6927). 72.9% leaves out quality.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-31","question":"Monthly sales of a product were 120, 135, 150 and 141 units (oldest first). What is the 3-month moving-average forecast for the next month?","options":["135","142","136.5","141"],"answer":1,"explanation":"Use the latest three months: (135 + 150 + 141) ÷ 3 = 426 ÷ 3 = 142. 136.5 averages all four months.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-32","question":"Sales were 200 (Jan), 220 (Feb) and 250 (Mar). Using a weighted moving average with weights 0.5, 0.3 and 0.2, the heaviest weight on the most recent month, what is the April forecast?","options":["231","216","223.33","250"],"answer":0,"explanation":"F = 0.5 × 250 + 0.3 × 220 + 0.2 × 200 = 125 + 66 + 40 = 231. Putting 0.5 on January instead gives 216; the simple average is 223.33.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-33","question":"Last period's forecast was 500 units and actual demand was 540 units. With exponential smoothing and α = 0.3, what is the next forecast?","options":["520","540","512","528"],"answer":2,"explanation":"F(new) = F + α(A − F) = 500 + 0.3 × 40 = 512. Using 0.7 as the weight on the error gives 528.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-34","question":"The forecast for period 1 was 100. Actual demand in periods 1, 2 and 3 was 110, 95 and 120. Using exponential smoothing with α = 0.2, what is the forecast for period 4?","options":["108.33","115.52","120","104.48"],"answer":3,"explanation":"F2 = 100 + 0.2(110 − 100) = 102; F3 = 102 + 0.2(95 − 102) = 100.6; F4 = 100.6 + 0.2(120 − 100.6) = 104.48. Swapping α and 1 − α (α = 0.8) gives 115.52.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-35","question":"Actual demand for four weeks was 100, 120, 80 and 150; the forecasts were 110, 110, 100 and 140. What is the MAPE?","options":["11.3%","12.5%","11.1%","2.5%"],"answer":1,"explanation":"Absolute % errors (divide by actual): 10/100 = 10%, 10/120 = 8.33%, 20/80 = 25%, 10/150 = 6.67%. MAPE = 50% ÷ 4 = 12.5%. Dividing by the forecast gives 11.3%; total error ÷ total demand (50/450) gives 11.1%.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-36","question":"Forecast errors (actual − forecast) for six months were +5, +8, −3, +7, +6 and +9. Control limits for the tracking signal are ±4. What is the tracking signal and what does it say?","options":["5.05; the method consistently under-forecasts","0.84; the method is in control","32; the method is in control","5.05; the method consistently over-forecasts"],"answer":0,"explanation":"Running sum of errors = 32; MAD = 38/6 = 6.333. TS = 32 ÷ 6.333 = 5.05, beyond +4. Positive errors mean actual > forecast, so the method under-forecasts.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-37","question":"Method X has forecast errors +4, −4, +4, −4. Method Y has errors 0, 0, 0, +12. Which statement is correct?","options":["Y has the lower MAD but the higher MSE","Both have the same MAD and MSE","X has both the lower MAD and the lower MSE","Y has both the lower MAD and the lower MSE"],"answer":0,"explanation":"X: MAD = 4, MSE = 16. Y: MAD = 12/4 = 3, MSE = 144/4 = 36. MSE squares errors, so it punishes Y's single large miss.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-38","question":"Quarterly sales (Q1–Q4) were 80, 120, 100, 140 in Year 1 and 100, 140, 110, 170 in Year 2. Seasonal indices are computed as (average for the quarter) ÷ (average of all quarters). If total sales next year are forecast at 1,040, what is the Q4 forecast?","options":["340","201.3","260","335.8"],"answer":3,"explanation":"Quarter averages: 90, 130, 105, 155; overall average = 120. Q4 index = 155/120 = 1.2917. Q4 forecast = (1,040/4) × 1.2917 = 335.8. Dividing by the index (deseasonalising) gives 201.3; 340 uses only Year 2's Q4 share.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-39","question":"A firm's trend line for annual sales (₹ crore) is ŷ = 120 + 8t, with t = 1 for 2019. What is the forecast for 2026?","options":["192","184","128","176"],"answer":1,"explanation":"2026 is t = 8 (2019 = 1). ŷ = 120 + 8 × 8 = 184. Using t = 7 gives 176.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-40","question":"Annual demand is 2,400 units, ordering cost ₹200 per order and holding cost ₹6 per unit per year. What is the EOQ?","options":["566 units","160 units","400 units","283 units"],"answer":2,"explanation":"EOQ = √(2DS/H) = √(2 × 2,400 × 200 ÷ 6) = √160,000 = 400. Leaving out the 2 gives √80,000 ≈ 283.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-41","question":"Annual demand is 12,000 units and the EOQ is 600 units. The firm works 300 days a year. How often is an order placed?","options":["Every 20 days","Every 15 days","Every 18.25 days","Every 50 days"],"answer":1,"explanation":"Orders per year = 12,000 ÷ 600 = 20. Time between orders = 300 working days ÷ 20 = 15 days. Using 365 days gives 18.25; 20 is the number of orders.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-42","question":"Annual demand is 6,000 units, ordering cost ₹150 per order, unit price ₹20 and holding cost 25% of price per year. What is the total annual ordering-plus-holding cost at the EOQ?","options":["₹1,500","₹123,000","₹4,500","₹3,000"],"answer":3,"explanation":"H = 0.25 × 20 = ₹5. EOQ = √(2 × 6,000 × 150 ÷ 5) = √360,000 = 600. Ordering = (6,000/600) × 150 = ₹1,500; holding = (600/2) × 5 = ₹1,500; total ₹3,000. ₹123,000 adds the purchase cost.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-43","question":"For the item with D = 6,000, S = ₹150 and H = ₹5 (EOQ = 600), the buyer instead orders 900 units each time. How much extra ordering-plus-holding cost does this add per year?","options":["₹250","₹500","₹750","₹1,250"],"answer":0,"explanation":"At Q = 900: ordering = (6,000/900) × 150 = ₹1,000; holding = 450 × 5 = ₹2,250; total ₹3,250. At EOQ the total is ₹3,000, so the penalty is ₹250. ₹750 counts only the extra holding and ignores the ₹500 saved on ordering.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-44","question":"D = 6,000 units/yr, S = ₹150 per order, holding cost = 25% of unit price per year. The supplier charges ₹20 per unit for orders below 1,000 units and ₹19 per unit for orders of 1,000 or more. What order quantity minimises total annual cost (including purchase), and what is that cost?","options":["600 units; ₹123,000","1,000 units; ₹117,400","1,000 units; ₹117,275","616 units; ₹116,924"],"answer":2,"explanation":"EOQ at ₹19 = √(2×6,000×150 ÷ 4.75) ≈ 616, below the 1,000 break, so it is infeasible at that price. Compare: Q = 600 at ₹20 → 120,000 + 1,500 + 1,500 = ₹123,000; Q = 1,000 at ₹19 → 114,000 + 900 + 500 × 4.75 = ₹117,275. Take the discount. ₹117,400 keeps holding cost at ₹5 instead of 25% of ₹19.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-45","question":"Daily demand is 40 units, lead time is 6 days and the firm keeps 60 units of safety stock. What is the reorder point?","options":["300 units","240 units","280 units","360 units"],"answer":0,"explanation":"ROP = demand during lead time + safety stock = 40 × 6 + 60 = 300. 240 leaves out safety stock.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-46","question":"Average daily demand is 50 units with a standard deviation of 8 units per day; the lead time is a constant 9 days. For a 95% cycle-service level (z = 1.65), what is the reorder point?","options":["463.2 units","489.6 units","450.0 units","568.8 units"],"answer":1,"explanation":"σ over lead time = 8 × √9 = 24. Safety stock = 1.65 × 24 = 39.6. ROP = 50 × 9 + 39.6 = 489.6. Multiplying σ by 9 instead of √9 gives 568.8.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-47","question":"Daily demand averages 100 units (σ = 20 units/day). Lead time averages 4 days (σ = 1 day); demand and lead time are independent. For z = 2.33, what safety stock is needed (nearest unit)?","options":["326 units","96 units","93 units","251 units"],"answer":3,"explanation":"σ(LTD) = √(L·σd² + d²·σL²) = √(4 × 400 + 100² × 1) = √11,600 = 107.7. SS = 2.33 × 107.7 ≈ 251. Ignoring lead-time variability gives 2.33 × 40 ≈ 93; adding the σ's linearly gives 326.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-48","question":"Annual usage and unit cost of six items: P 500 units at ₹400; Q 10,000 at ₹2; R 2,000 at ₹50; S 50 at ₹600; T 8,000 at ₹5; U 1,000 at ₹10. If class A covers roughly the top 75% of annual consumption value, which items are class A?","options":["Q and T","P, R and T","P and R","P and S"],"answer":2,"explanation":"Annual values: P ₹2,00,000; R ₹1,00,000; T ₹40,000; S ₹30,000; Q ₹20,000; U ₹10,000; total ₹4,00,000. P (50%) + R (25%) = 75%. Q and T have the most units, and P and S the highest unit prices, but ABC ranks by value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-49","question":"Match each inventory classification with its basis.\n1. ABC  2. VED  3. FSN  4. HML\na. Rate of movement (issues)  b. Criticality to operations  c. Annual consumption value  d. Unit price","options":["1-c, 2-a, 3-b, 4-d","1-d, 2-b, 3-a, 4-c","1-a, 2-b, 3-c, 4-d","1-c, 2-b, 3-a, 4-d"],"answer":3,"explanation":"ABC = annual consumption value; VED = vital/essential/desirable (criticality); FSN = fast/slow/non-moving; HML = high/medium/low unit price.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-50","question":"Which of the following cause the bullwhip effect in a supply chain?\nI. Each tier updating its forecast from the orders it receives\nII. Ordering in large batches\nIII. Everyday low pricing\nIV. Inflated orders when supply is rationed","options":["II and III only","I, II, III and IV","I, II and IV only","I and IV only"],"answer":2,"explanation":"Demand-signal processing, order batching, price fluctuations and rationing (shortage gaming) cause bullwhip. Everyday low pricing removes promotion-driven forward buying, so it reduces bullwhip.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-51","question":"Assertion (A): Vendor-managed inventory (VMI) tends to dampen the bullwhip effect.\nReason (R): Under VMI the supplier sees the retailer's actual consumption data instead of only its orders.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: the supplier plans from real demand rather than from distorted, batched orders, which removes one layer of signal amplification.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-52","question":"A firm makes a part in-house. Annual demand is 18,000 units (300 working days, so 60 units/day). The production rate is 100 units/day, setup cost ₹900 per run and holding cost ₹6 per unit per year. What is the economic production quantity (nearest unit)?","options":["3,000 units","3,674 units","1,470 units","2,324 units"],"answer":1,"explanation":"EPQ = √[2DS ÷ (H(1 − d/p))] = √[2 × 18,000 × 900 ÷ (6 × 0.4)] = √13,500,000 ≈ 3,674. Plain EOQ gives 2,324; 1,470 is the maximum inventory; using d/p instead of 1 − d/p gives 3,000.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-53","question":"Annual demand for an item rises by 44% while the ordering cost per order falls by 19%. Holding cost is unchanged. By what percentage does the EOQ change?","options":["Rises by 11.8%","Rises by 25%","Rises by 8%","Rises by 16.64%"],"answer":2,"explanation":"EOQ ∝ √(D × S). New/old = √(1.44 × 0.81) = √1.1664 = 1.08, an 8% rise. 16.64% forgets the square root; 25% simply nets 44 − 19.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-54","question":"Under a periodic-review system, stock is reviewed every 14 days and the supplier lead time is 7 days. Daily demand averages 30 units (σ = 6 units/day). For z = 1.65, how much should be ordered at a review when 250 units are on hand and nothing is on order (nearest unit)?","options":["588 units","380 units","207 units","425 units"],"answer":3,"explanation":"The protection period is T + L = 21 days. Order-up-to level = 30 × 21 + 1.65 × 6 × √21 = 630 + 45.4 = 675.4. Order = 675.4 − 250 ≈ 425. 380 leaves out safety stock; covering only the review period gives 207.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-55","question":"A kiosk buys a magazine at ₹30, sells it at ₹60 and returns unsold copies for ₹10 each. Demand is uniformly distributed between 100 and 200 copies. How many copies should it stock?","options":["175","160","150","140"],"answer":1,"explanation":"Underage cost Cu = 60 − 30 = 30; overage cost Co = 30 − 10 = 20. Critical ratio = 30/(30 + 20) = 0.6. Q = 100 + 0.6 × 100 = 160. Using Co/(Cu + Co) = 0.4 gives 140; stocking the mean gives 150.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-56","question":"The standard deviation of lead-time demand is 50 units and holding cost is ₹10 per unit per year. Raising the cycle-service level from 95% (z = 1.645) to 99% (z = 2.33) adds how much annual holding cost ?","options":["₹342.50","₹685.00","₹822.50","₹1,165.00"],"answer":0,"explanation":"Extra safety stock = (2.33 − 1.645) × 50 = 34.25 units. Extra cost = 34.25 × 10 = ₹342.50. ₹1,165 is the whole 99% safety-stock cost, not the increase.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-57","question":"Which statement is true at the economic order quantity in the basic EOQ model?","options":["Annual purchase cost is at its minimum","Annual ordering cost equals annual holding cost","Annual holding cost is twice the annual ordering cost","The number of orders per year equals the EOQ"],"answer":1,"explanation":"In the basic model total cost DS/Q + QH/2 is lowest where its two parts are equal, so at EOQ ordering cost = holding cost. Purchase cost does not depend on Q in this model.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-58","question":"For an item ordered at its EOQ, the annual holding cost is ₹4,500. Annual demand is 9,000 units and each order costs ₹250. What is the holding cost per unit per year?","options":["₹18","₹36","₹9","₹25"],"answer":0,"explanation":"At EOQ ordering cost = holding cost = ₹4,500, so DS/Q = 4,500 → Q = 9,000 × 250 ÷ 4,500 = 500. Holding = (Q/2) × H → 4,500 = 250 × H → H = ₹18. ₹9 divides by Q instead of Q/2.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-59","question":"An item's reorder point is 500 units. Right now there are 320 units on hand, 300 units on an open purchase order and 20 units backordered by customers. What should the planner do?","options":["Place an order; the inventory position is 300","No order; the inventory position is 640","Place an order; on-hand stock of 320 is below 500","No order; the inventory position is 600"],"answer":3,"explanation":"Reorder decisions use the inventory position = on hand + on order − backorders = 320 + 300 − 20 = 600, which is above 500. Adding the backorders instead of subtracting gives 640.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-60","question":"In a four-tier supply chain, the variance of weekly consumer demand is 100. The retailer's orders have variance 160, the distributor's orders 300 and the factory's production plan 540. What is the bullwhip ratio at the distributor?","options":["5.4","1.6","1.875","3.0"],"answer":2,"explanation":"Bullwhip ratio at a tier = variance of orders it places ÷ variance of orders it receives = 300 ÷ 160 = 1.875. 3.0 compares with consumer demand; 5.4 is the factory's ratio to consumer demand.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-61","question":"A batch of 500 circuit boards is inspected; each board has 4 opportunities for a defect. Inspectors find 30 defects. What is the DPMO?","options":["15,000","60,000","1,500","7,500"],"answer":0,"explanation":"DPMO = defects ÷ (units × opportunities) × 10⁶ = 30 ÷ 2,000 × 10⁶ = 15,000. Ignoring opportunities gives 30/500 × 10⁶ = 60,000.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-62","question":"Defect counts last month: scratches 84, dents 56, misalignment 30, paint runs 18, other 12. Using Pareto analysis, what is the smallest number of categories that together account for at least 80% of defects?","options":["4","2","3","1"],"answer":2,"explanation":"Total = 200. Cumulative shares: scratches 42%, + dents 70%, + misalignment 85%. Three categories reach 80%; two stop at 70%.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-63","question":"Which of the following is NOT one of the classic seven wastes of lean production?","options":["Waiting","Standardised work","Overproduction","Over-processing"],"answer":1,"explanation":"The seven wastes (TIMWOOD) are transport, inventory, motion, waiting, overproduction, over-processing and defects. Standardised work is a lean tool for removing waste, not a waste.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-64","question":"Twenty samples of size 5 give a grand mean of 50.0 mm and an average range of 4.0 mm. With A2 = 0.577 for n = 5, what is the upper control limit of the X̄-chart?","options":["55.37 mm","56.92 mm","54.00 mm","52.31 mm"],"answer":3,"explanation":"UCL = X̿ + A2·R̄ = 50 + 0.577 × 4 = 52.31 mm. Treating R̄ as σ (50 + 3 × 4/√5) gives 55.37; A2 already contains the factor 3, so multiplying by 3 again gives 56.92.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-65","question":"Twenty-five samples of 200 items each contain 250 defectives in total. What are the 3-sigma control limits of the p-chart?","options":["LCL = 0.0408, UCL = 0.0592","LCL = 0, UCL = 0.0962","LCL = 0.0038, UCL = 0.0962","LCL = 0.0192, UCL = 0.0808"],"answer":2,"explanation":"p̄ = 250 ÷ 5,000 = 0.05. σp = √(0.05 × 0.95 ÷ 200) = 0.01541. Limits = 0.05 ± 3 × 0.01541 = 0.0038 to 0.0962. The LCL is positive, so it is not set to 0. Using n = 5,000 (all items) shrinks σ wrongly.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-66","question":"A process is monitored with X̄ and R charts (n = 4): X̿ = 25, R̄ = 6.2, A2 = 0.729, D3 = 0, D4 = 2.282. Three new samples are taken: S1 = 27, 30, 24, 33; S2 = 19, 34, 25, 22; S3 = 31, 26, 34, 29. Which samples signal that the process is out of control?","options":["S3 only","S2 and S3 only","S1, S2 and S3","None of them"],"answer":1,"explanation":"X̄ limits = 25 ± 0.729 × 6.2 = 20.48 to 29.52; R limits = 0 to 2.282 × 6.2 = 14.15. S1: mean 28.5, range 9 → in control. S2: mean 25, range 15 → range out. S3: mean 30, range 8 → mean out. Checking only the X̄-chart misses S2.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-67","question":"A shaft's diameter specification is 10.0 ± 0.6 mm. The process mean is 10.2 mm and the standard deviation is 0.15 mm. What is Cpk?","options":["0.44","1.78","1.33","0.89"],"answer":3,"explanation":"Cp = (10.6 − 9.4) ÷ (6 × 0.15) = 1.33. Cpk = min(10.6 − 10.2, 10.2 − 9.4) ÷ (3 × 0.15) = 0.4 ÷ 0.45 = 0.89. Using the far side (0.8) gives 1.78; dividing by 6σ gives 0.44.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-68","question":"A part passes through three steps whose first-pass yields are 98%, 95% and 97%. What is the rolled throughput yield?","options":["90.3%","96.7%","95.0%","90.0%"],"answer":0,"explanation":"RTY = product of first-pass yields = 0.98 × 0.95 × 0.97 = 0.9031 ≈ 90.3%. Averaging gives 96.7%; subtracting the losses (2 + 5 + 3 = 10%) gives 90.0%.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-69","question":"A call centre audits 25,000 calls; each call has 5 defect opportunities, and 780 defects are found. Reference values (with the 1.5σ shift): 3σ = 66,807 DPMO, 4σ = 6,210 DPMO, 5σ = 233 DPMO. Which description is correct?","options":["DPMO = 31,200; between 3σ and 4σ","DPMO = 6,240; slightly above 4σ","DPMO = 1,248; between 4σ and 5σ","DPMO = 6,240; slightly below 4σ"],"answer":3,"explanation":"DPMO = 780 ÷ (25,000 × 5) × 10⁶ = 6,240. That is a little more than 6,210, so the process is slightly worse than (below) 4σ. Ignoring the 5 opportunities gives 31,200.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-70","question":"Match each quality tool with its main use.\n1. Pareto chart  2. Cause-and-effect (fishbone) diagram  3. Control chart  4. Scatter diagram\na. Separate common-cause from special-cause variation  b. Show a possible relationship between two variables  c. Pick out the vital few problem categories  d. Organise possible root causes into categories","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-a, 2-d, 3-c, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Pareto ranks problems to find the vital few; fishbone organises causes (man, machine, method, material …); control charts separate common and special causes; scatter diagrams show relationships.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-71","question":"Assertion (A): A process can be in statistical control and still produce many units outside specification.\nReason (R): Control limits come from the process's own variation, whereas specification limits are set by the customer or designer.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true and R explains A: a stable but wide (or off-centre) process stays within its control limits while many units fall outside specification.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-72","question":"Which statements are correct?\nI. Poka-yoke aims to make errors impossible or immediately obvious.\nII. Kaizen relies mainly on large, infrequent breakthrough projects.\nIII. The 5S are Sort, Set in order, Shine, Standardise and Sustain.\nIV. Jidoka means a machine or line stops automatically when an abnormality is detected.","options":["II, III and IV only","I, II, III and IV","I, III and IV only","I and II only"],"answer":2,"explanation":"Kaizen is continuous, incremental improvement by everyone, the opposite of occasional breakthroughs, so II is false. The others are correct definitions.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-73","question":"A firm's annual quality costs (₹ lakh): employee quality training 4, incoming inspection 6, scrap 9, warranty claims 11, supplier certification 2, calibration of test equipment 3, rework 5. What share of the total cost of quality is failure cost?","options":["27.5%","62.5%","50.0%","37.5%"],"answer":1,"explanation":"Prevention = 4 + 2 = 6; appraisal = 6 + 3 = 9; internal failure = 9 + 5 = 14; external failure = 11. Total = 40. Failure = 25 ÷ 40 = 62.5%. 50% forgets rework; 37.5% is the cost of conformance.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-74","question":"Using the Taguchi loss function, a deviation of 0.5 mm from target causes a loss of ₹200 per unit. What is the loss for a unit that is 0.2 mm off target?","options":["₹128","₹16","₹80","₹32"],"answer":3,"explanation":"L = k(x − T)². k = 200 ÷ 0.5² = 800. Loss = 800 × 0.2² = ₹32. A straight-line (proportional) assumption gives ₹80.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-75","question":"A project's activities (duration in days; immediate predecessors): A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G). What is the project duration?","options":["14 days","29 days","11 days","16 days"],"answer":0,"explanation":"Paths: A–C–F–H = 14; A–D–G–H = 14; B–E–G–H = 11. The longest path(s) give 14 days, and here there are two critical paths. 29 is the sum of all durations.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-76","question":"For the project A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G), what are the total float and the free float of activity B?","options":["Total float 0, free float 0","Total float 3, free float 3","Total float 3, free float 0","Total float 0, free float 3"],"answer":2,"explanation":"B: ES 0, EF 4. G's latest start = 14 − 2 − 3 = 9, so E's LF = 9, E's LS = 7 and B's LF = 7 → total float = 3. B's only successor E has ES = 4 = B's EF, so free float = 0. The float belongs to the B–E chain as a whole.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-77","question":"For the project A 3 (–), B 4 (–), C 5 (A), D 6 (A), E 2 (B), F 4 (C), G 3 (D, E), H 2 (F, G), what is the earliest start of activity G?","options":["Day 12","Day 9","Day 6","Day 7"],"answer":1,"explanation":"G needs both D and E. EF(D) = 3 + 6 = 9; EF(E) = 4 + 2 = 6. ES(G) = max(9, 6) = 9. Taking the minimum (6) is the classic forward-pass error.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-78","question":"A small project has two parallel paths. Path 1 is A (4 days) → C (6 days); path 2, parallel to it, is B (5 days) → D (4 days). Crash cost per day and maximum crash: A ₹500 (1 day), C ₹300 (2 days), B ₹400 (2 days), D ₹200 (1 day). What is the minimum crashing cost to finish the project in 8 days?","options":["₹500","₹1,000","₹600","₹800"],"answer":3,"explanation":"Normal length = 10 days (A–C); B–D = 9. Day 10 → 9: crash C (₹300); now both paths are 9. Day 9 → 8: both paths must shrink, so crash C again (₹300) and D (₹200). Total = ₹800. ₹600 crashes C twice and forgets that B–D has become critical.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-79","question":"Path 1 is A (4 days) → C (6 days); path 2, parallel to it, is B (5 days) → D (4 days). Crash cost per day and maximum crash: A ₹500 (1 day), C ₹300 (2 days), B ₹400 (2 days), D ₹200 (1 day). Indirect (overhead) cost is ₹450 per day and the normal duration is 10 days. Which project duration minimises total cost?","options":["8 days","7 days","9 days","10 days"],"answer":2,"explanation":"10 → 9: crash C for ₹300 and save ₹450 → worth it. 9 → 8: both paths now critical; cheapest pair is C + D = ₹500 > ₹450 → not worth it. Total costs: 10 days ₹4,500, 9 days ₹4,350, 8 days ₹4,400. Optimum = 9 days.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-80","question":"A PERT activity has an optimistic time of 4 days, most likely 7 days and pessimistic 16 days. What are its expected time and variance?","options":["8 days; variance 4","8 days; variance 144","8 days; variance 2","9 days; variance 4"],"answer":0,"explanation":"te = (a + 4m + b)/6 = (4 + 28 + 16)/6 = 8 days. σ = (b − a)/6 = 12/6 = 2, so variance = 4. A simple average (4 + 7 + 16)/3 = 9 ignores the weight on m.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-81","question":"The critical path of a project has three activities with PERT estimates (a, m, b) in days: (2, 4, 6), (3, 5, 13) and (4, 6, 8). Assuming a normal distribution, what is the probability (approximately) of finishing within 18 days?","options":["15%","75%","85%","70%"],"answer":2,"explanation":"te = 4 + 6 + 6 = 16 days. Variances: 0.444 + 2.778 + 0.444 = 3.667; σ = 1.915. z = (18 − 16)/1.915 = 1.04 → P ≈ 85%. Adding standard deviations instead of variances gives σ = 3 and ≈ 75%.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-82","question":"A project's critical path has an expected length of 40 days and a standard deviation of 3 days. What due date gives a 95% chance of on-time completion (z = 1.645)?","options":["35.1 days","44.9 days","46.0 days","49.0 days"],"answer":1,"explanation":"Due date = 40 + 1.645 × 3 = 44.9 days. Adding the variance (9) gives 49; 35.1 is the 5% point on the wrong side.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-83","question":"In an activity-on-arrow project network, a dummy activity:","options":["represents waiting time for resources","takes the average duration of its neighbours","is always on the critical path","takes no time or resources and only shows a dependency"],"answer":3,"explanation":"Dummies (dashed arrows) carry zero time and cost; they keep event numbering unique and show logical dependencies.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-84","question":"Activities (days; predecessors): A 5 (–), B 3 (–), C 8 (A), D 4 (A, B), E 6 (B), F 3 (C, D), G 7 (D, E), H 4 (F), I 2 (G). If activity G is delayed by 3 days, what does the project duration become?","options":["21 days","23 days","19 days","20 days"],"answer":0,"explanation":"Critical path A–C–F–H = 20 days. G: ES = max(EF D = 9, EF E = 9) = 9, LF = 20 − 2 = 18, LS = 11 → total float 2. A 3-day delay uses the 2 days of float and pushes the end out by 1 day: 21 days. 23 assumes G is critical.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-85","question":"Which statements about float in CPM are correct?\nI. Free float can never exceed total float.\nII. Using up an activity's free float delays the early start of its successors.\nIII. When the deadline equals the critical-path length, critical activities have zero total float.\nIV. Total float is shared by the activities along a non-critical chain.","options":["II, III and IV only","I and II only","I, III and IV only","I, II, III and IV"],"answer":2,"explanation":"Free float is exactly the delay possible without disturbing any successor's early start, so II is false. The rest are true; using total float on one activity reduces what is left for the others on that chain.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-86","question":"An activity's normal time is 10 days at a cost of ₹20,000; its crash time is 6 days at ₹32,000. What is its crash cost per day?","options":["₹3,200","₹3,000","₹1,200","₹2,000"],"answer":1,"explanation":"Cost slope = (crash cost − normal cost) ÷ (normal time − crash time) = 12,000 ÷ 4 = ₹3,000 per day. ₹3,200 divides crash cost by 10; ₹1,200 divides by 10 days.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-87","question":"A project has two independent paths. Path 1: expected 30 days, variance 9. Path 2: expected 29 days, variance 25. What is the approximate probability that the whole project finishes within 32 days?","options":["75%","73%","63%","54%"],"answer":3,"explanation":"Both paths must finish. P(path 1 ≤ 32) = Φ(2/3) = 0.748; P(path 2 ≤ 32) = Φ(3/5) = 0.726. Product = 0.543 ≈ 54%. Using only the 'critical' path 1 gives 75% and overstates the chance, because path 2 has far more variance; pooling the two variances (√34) is also wrong because the paths run in parallel, not in series.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-88","question":"In CPM, the critical path is:","options":["the longest path through the network","the shortest path through the network","the path with the highest total cost","the path with the most activities"],"answer":0,"explanation":"The project cannot finish before its longest path, so that path decides the duration and has zero float.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-89","question":"A work cell uses 200 parts per hour. A container holds 30 parts and the replenishment lead time (waiting plus processing) is 45 minutes. With a 20% safety factor, how many kanban cards are needed?","options":["8","4","6","5"],"answer":2,"explanation":"N = D × L × (1 + α) ÷ C = 200 × 0.75 × 1.2 ÷ 30 = 6. Without the safety factor it is 5.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-90","question":"A dimension has specification 100 ± 6. The process standard deviation is 1.5 and its mean has drifted to 101.5. About how many parts per million fall outside specification?","options":["About 1,350","About 3.4","About 66,800","About 2,700"],"answer":0,"explanation":"Upper side: z = (106 − 101.5)/1.5 = 3 → tail ≈ 0.00135 = 1350 ppm. Lower side: z = (101.5 − 94)/1.5 = 5 → negligible. Total ≈ 1,350 ppm. 2,700 counts a 3σ tail on both sides, which applies only to a centred process with ±3σ specs.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-91","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. With x chairs and y tables, which is the correct LP formulation?","options":["Min 40x + 70y; 2x + 5y ≥ 100; 3x + 2y ≥ 84; x, y ≥ 0","Max 40x + 70y; 2x + 3y ≤ 100; 5x + 2y ≤ 84; x, y ≥ 0","Max 40x + 70y; 2x + 5y ≤ 84; 3x + 2y ≤ 100; x, y ≥ 0","Max 40x + 70y; 2x + 5y ≤ 100; 3x + 2y ≤ 84; x, y ≥ 0"],"answer":3,"explanation":"Each resource gives one constraint: carpentry 2x + 5y ≤ 100 and finishing 3x + 2y ≤ 84. Profit is maximised. The first distractor mixes up which coefficients belong to which product.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-92","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. What is the maximum weekly profit?","options":["₹1,120","₹1,640","₹1,720","₹1,400"],"answer":1,"explanation":"Corner points: (0, 0) → 0; (28, 0) → ₹1,120; (0, 20) → ₹1,400; and the intersection of 2x + 5y = 100 with 3x + 2y = 84, which is (20, 12) → 800 + 840 = ₹1,640. Making only tables (the higher-margin product) gives ₹1,400.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-93","question":"A workshop makes chairs (profit ₹40 each) and tables (profit ₹70 each). A chair needs 2 carpentry hours and 3 finishing hours; a table needs 5 carpentry hours and 2 finishing hours. 100 carpentry hours and 84 finishing hours are available per week. Both resources are binding at the optimum. What is the shadow price of one extra carpentry hour (to two decimals)?","options":["₹5.45","₹11.82","₹20.00","₹14.00"],"answer":1,"explanation":"Shadow prices (u carpentry, v finishing) satisfy the dual equalities 2u + 3v = 40 and 5u + 2v = 70 → u = 130/11 ≈ ₹11.82, v = 60/11 ≈ ₹5.45. Check: with 101 hours the optimum moves to (19.818, 12.273) and profit rises by 11.82. ₹14 (= 70/5) wrongly assumes only tables would be made.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-94","question":"Minimise C = 3x + 2y subject to x + y ≥ 8, x + 3y ≥ 12, 2x + y ≥ 10, x, y ≥ 0. What is the minimum value of C?","options":["18","20","22","36"],"answer":0,"explanation":"The feasible region is unbounded upward, with corner points (0, 10) → 20, (2, 6) → 18, (6, 2) → 22 and (12, 0) → 36. Because we minimise and the cost coefficients are positive, the optimum is the cheapest corner: (2, 6), C = 18.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-95","question":"In a two-variable LP solved graphically, the iso-profit line turns out to be parallel to a binding edge of the feasible region at the optimum. What does this indicate?","options":["The solution is degenerate","The problem is unbounded","The problem is infeasible","Multiple (alternative) optimal solutions"],"answer":3,"explanation":"When the objective is parallel to a boundary edge that it touches last, every point on that edge, including both end corners, gives the same optimal value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-96","question":"Which statements about linear programming are correct?\nI. The feasible region of an LP is a convex set.\nII. If an optimal solution exists, at least one corner point is optimal.\nIII. A constraint with positive slack at the optimum has a positive shadow price.\nIV. Adding a constraint can never improve the optimal objective value.","options":["I, II, III and IV","II, III and IV only","I, II and IV only","I and III only"],"answer":2,"explanation":"A non-binding constraint (positive slack) has a shadow price of zero (complementary slackness), so III is false. Adding a constraint can only shrink or keep the feasible region, so the optimum can only stay or get worse.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-97","question":"Maximise Z = 7x + 5y subject to x + 2y ≤ 14, 3x + y ≤ 18, x − y ≤ 4, x, y ≥ 0. What is the optimal value of Z?","options":["54.8","42","46","35"],"answer":0,"explanation":"Corner points: (0, 0) → 0; (0, 7) → 35; (4, 0) → 28; (5.5, 1.5) [3x + y = 18 with x − y = 4] → 46; (4.4, 4.8) [x + 2y = 14 with 3x + y = 18] → 30.8 + 24 = 54.8. The optimum is at (4.4, 4.8). Stopping at the first intersection found (5.5, 1.5) gives 46.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-98","question":"An LP has the constraints x + y ≤ 4 and x + y ≥ 6 (with x, y ≥ 0). What can be said about it?","options":["It has alternative optima","It has a unique optimum at (4, 0)","It is infeasible","It is unbounded"],"answer":2,"explanation":"No point can have x + y both at most 4 and at least 6, so the feasible region is empty.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-99","question":"A transportation problem has supplies of 120, 80 and 100 units at three plants and demands of 90, 110 and 70 units at three markets. How should it be balanced before solving?","options":["Add a dummy plant with supply 30 and zero transport cost","Add a dummy market with demand 30 and zero transport cost","No change is needed; it is already balanced","Reduce the largest supply by 30"],"answer":1,"explanation":"Total supply = 300, total demand = 270. The excess supply of 30 goes to a dummy destination (column) with zero cost; that allocation is stock left unshipped at the plants.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-100","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. What is the total cost of the initial solution found by the North-West Corner Rule?","options":["₹1,710","₹1,560","₹2,040","₹2,280"],"answer":3,"explanation":"NWCR: P1→M1 50 (₹400), P1→M2 10 (₹60), P2→M2 60 (₹720), P2→M3 20 (₹140), P3→M3 60 (₹960). Total = ₹2,280. NWCR ignores costs, which is why it is usually the worst starting solution; ₹1,710 is the least-cost method.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-101","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. What is the total cost of the initial solution found by Vogel's Approximation Method?","options":["₹1,620","₹1,560","₹1,710","₹2,280"],"answer":1,"explanation":"Round 1 penalties (gap between the two cheapest cells): P1 2, P2 2, P3 5, M1 1, M2 3, M3 3. P3 is largest → its cheapest cell P3→M2 gets 60 (₹540), exhausting P3. Round 2: M2 now has penalty 12 − 6 = 6, the largest → P1→M2 gets the remaining 10 (₹60). Round 3: M3 penalty 10 − 7 = 3 → P2→M3 80 (₹560). Finally P1→M1 50 (₹400). Total = ₹1,560, which here is already optimal. The least-cost method gives ₹1,710 and NWCR ₹2,280.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-102","question":"Unit transport costs (₹) from plants P1, P2, P3 (rows) to markets M1, M2, M3 (columns): P1: 8, 6, 10; P2: 9, 12, 7; P3: 14, 9, 16. Supplies: P1 60, P2 80, P3 60. Demands: M1 50, M2 70, M3 80. Starting from the North-West Corner solution, the MODI (u–v) method is applied with u1 = 0. Which unused cell enters the basis, and what is its reduced cost cij − ui − vj?","options":["P1→M3, +9","P3→M1, −9","P2→M1, −5","P3→M2, −12"],"answer":3,"explanation":"Basic cells give u1 = 0, v1 = 8, v2 = 6, u2 = 6, v3 = 1, u3 = 15. Reduced costs: P1→M3 = 10 − 0 − 1 = +9; P2→M1 = 9 − 6 − 8 = −5; P3→M1 = 14 − 15 − 8 = −9; P3→M2 = 9 − 15 − 6 = −12. The most negative, P3→M2, enters.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-103","question":"A transportation problem has 4 sources and 5 destinations. An initial basic feasible solution has 7 occupied cells. What does this mean?","options":["The solution is degenerate; it needs 8 occupied cells","The solution is optimal","The solution is non-degenerate","The problem is unbalanced"],"answer":0,"explanation":"A non-degenerate basic solution has m + n − 1 = 4 + 5 − 1 = 8 allocations. With only 7, an ε allocation must be added before MODI can compute all ui and vj.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-104","question":"Three jobs must be assigned one each to three workers. Costs (₹ hundred), rows = jobs J1–J3, columns = workers W1–W3: J1: 9, 11, 14; J2: 6, 15, 13; J3: 12, 13, 6. What is the minimum total cost?","options":["30","21","23","33"],"answer":2,"explanation":"Check the assignments: J1→W2, J2→W1, J3→W3 = 11 + 6 + 6 = 23, the lowest of the six possibilities. 21 adds each row's minimum (9 + 6 + 6) but uses W1 twice; 30 is the diagonal.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-105","question":"Four salespersons P, Q, R, S are to be assigned one each to territories T1–T4. Expected monthly sales (₹ lakh), columns T1–T4: P: 38, 40, 28, 33; Q: 31, 37, 35, 26; R: 42, 34, 30, 29; S: 27, 32, 36, 30. What is the maximum total sales?","options":["₹144 lakh","₹155 lakh","₹135 lakh","₹148 lakh"],"answer":3,"explanation":"Best assignment: P→T4, Q→T2, R→T1, S→T3 = 148. Grabbing the largest cell each time (R→T1 42, P→T2 40, then S→T3 36, Q→T4 26) gives 144; adding each row's maximum (155) is not a valid assignment. For the Hungarian method, first convert to a loss matrix by subtracting every entry from 42.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-106","question":"When the Hungarian method is used for a maximisation assignment problem, what is the first step?","options":["Subtract every entry from the largest entry in the matrix","Subtract each row's maximum from that row","Multiply all entries by −1 and stop","Add a dummy row of zeros"],"answer":0,"explanation":"Converting to an opportunity-loss matrix (largest entry − each entry) turns maximisation into minimisation; the usual row and column reductions then follow. Multiplying by −1 also works, but only if the reductions continue afterwards.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-107","question":"Assertion (A): The assignment problem is a special case of the transportation problem.\nReason (R): In an assignment problem every supply and every demand equals 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true, and R explains A: with unit supplies and demands, the transportation model becomes the one-to-one assignment model (which is highly degenerate, so the Hungarian method is used instead of MODI).","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-108","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Which plant does an optimist using the maximax criterion choose?","options":["Medium","Small","Large","Medium or Large equally"],"answer":2,"explanation":"Maximax takes each option's best payoff (Small 50, Medium 80, Large 120) and picks the largest: Large.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-109","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Which plant does the maximin (pessimist) criterion select?","options":["Large","Small","Small or Medium equally","Medium"],"answer":1,"explanation":"Worst payoffs: Small 40, Medium 20, Large −30. Maximin picks the best of these worst cases: Small.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-110","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Probabilities of low, medium and high demand are 0.3, 0.5 and 0.2. Which plant has the highest expected monetary value, and what is it?","options":["Large, ₹40 lakh","Medium, ₹53.33 lakh","Small, ₹44.5 lakh","Medium, ₹52 lakh"],"answer":3,"explanation":"EMV Small = 12 + 22.5 + 10 = 44.5; Medium = 6 + 30 + 16 = 52; Large = −9 + 25 + 24 = 40. Best: Medium, ₹52 lakh. ₹53.33 lakh is the equal-weight (Laplace) average.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-111","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Under the minimax-regret criterion, which plant is chosen and what is its maximum regret?","options":["Small, ₹70 lakh","Medium, ₹20 lakh","Medium, ₹40 lakh","Large, ₹70 lakh"],"answer":2,"explanation":"Column bests: 40, 60, 120. Regrets: Small 0, 15, 70 (max 70); Medium 20, 0, 40 (max 40); Large 70, 10, 0 (max 70). Minimax regret = Medium with 40. ₹20 lakh is Medium's regret under low demand only.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-112","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Probabilities of low, medium and high demand are 0.3, 0.5 and 0.2. What is the expected value of perfect information (EVPI)?","options":["₹68 lakh","₹14 lakh","₹26 lakh","₹66 lakh"],"answer":1,"explanation":"With perfect information the firm picks the best plant for each state: 0.3 × 40 + 0.5 × 60 + 0.2 × 120 = 66. Best EMV without it = 52 (Medium). EVPI = 66 − 52 = ₹14 lakh. 66 is EV under certainty, not the value of the information.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-113","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Using the Hurwicz criterion with coefficient of optimism α = 0.6, which plant is chosen?","options":["Large, with a score of 60","Medium, with a score of 56","Small, with a score of 46","Medium, with a score of 44"],"answer":0,"explanation":"Score = α × best + (1 − α) × worst. Small 0.6×50 + 0.4×40 = 46; Medium 0.6×80 + 0.4×20 = 56; Large 0.6×120 + 0.4×(−30) = 60. Large wins. Swapping the weights would give Medium 44.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-114","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Keeping P(low demand) at 0.3, how large must P(high demand) be for the Large plant to have the highest EMV?","options":["More than 0.50","More than 0.27","More than 0.44","More than 0.20"],"answer":2,"explanation":"Let P(high) = p, so P(medium) = 0.7 − p. EMV Small = 43.5 + 5p; Medium = 48 + 20p; Large = 26 + 70p. Large beats Medium when 70p − 20p > 22 → p > 0.44; it beats Small already when p > 0.27, but Medium is the real rival.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-115","question":"A firm can launch a product now: success (probability 0.4) earns ₹100 lakh, failure loses ₹50 lakh; not launching earns 0. A test market reports 'favourable' with probability 0.8 if the product will succeed and 0.3 if it will fail. If the test result is favourable, what is the revised probability of success?","options":["0.80","0.64","0.32","0.50"],"answer":1,"explanation":"P(fav) = 0.8 × 0.4 + 0.3 × 0.6 = 0.32 + 0.18 = 0.50. P(success | fav) = 0.32 ÷ 0.50 = 0.64 (Bayes). 0.80 confuses P(fav | success) with P(success | fav).","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-116","question":"A firm can launch a product now: success (probability 0.4) earns ₹100 lakh, failure loses ₹50 lakh; not launching earns 0. A test market reports 'favourable' with probability 0.8 if the product will succeed and 0.3 if it will fail. What is the most the firm should pay for the test market (the expected value of sample information)?","options":["₹23 lakh","₹10 lakh","₹30 lakh","₹13 lakh"],"answer":3,"explanation":"Without the test: EMV(launch) = 40 − 30 = ₹10 lakh. Favourable (prob 0.5): P(S) = 0.64 → EMV = 64 − 18 = ₹46 lakh → launch. Unfavourable (prob 0.5): P(S) = 0.08/0.5 = 0.16 → EMV = 16 − 42 = −26 → do not launch (0). EV with test = 0.5 × 46 + 0.5 × 0 = ₹23 lakh. EVSI = 23 − 10 = ₹13 lakh. ₹30 lakh is EVPI, an upper bound.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-117","question":"Assertion (A): The action with the highest EMV is also the action with the lowest expected opportunity loss (EOL).\nReason (R): For every action, EMV + EOL equals the expected value under perfect information.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both true and R explains A: since EMV + EOL is the same constant for every action, maximising EMV is the same as minimising EOL, and the minimum EOL equals EVPI.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-118","question":"A firm must choose a plant size. Payoffs (₹ lakh) under low, medium and high demand: Small 40, 45, 50; Medium 20, 60, 80; Large −30, 50, 120. Using the Laplace (equal-likelihood) criterion, which plant is chosen?","options":["Small, average ₹45 lakh","Medium, average ₹53.33 lakh","Large, average ₹46.67 lakh","Medium, average ₹52 lakh"],"answer":1,"explanation":"Laplace gives each state probability 1/3. Averages: Small 135/3 = 45; Medium 160/3 = 53.33; Large 140/3 = 46.67. Medium. ₹52 lakh is its EMV with the given probabilities, not the Laplace value.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-119","question":"Which decision criterion under uncertainty reflects a pessimistic decision-maker who looks only at the worst outcome of each option?","options":["Maximax","Laplace","Minimax regret","Maximin"],"answer":3,"explanation":"Maximin picks the option whose worst payoff is best. Maximax is optimistic; minimax regret minimises the largest opportunity loss; Laplace weights states equally.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-120","question":"A venture pays ₹100 lakh with probability 0.5 and nothing otherwise. The owner says she is indifferent between the venture and a sure ₹40 lakh. What are the risk premium and her risk attitude?","options":["₹10 lakh; risk-seeking","₹60 lakh; risk-neutral","₹10 lakh; risk-averse","₹40 lakh; risk-averse"],"answer":2,"explanation":"EMV = ₹50 lakh; certainty equivalent = ₹40 lakh. Risk premium = 50 − 40 = ₹10 lakh. Accepting less than the EMV for certainty means she is risk-averse.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-121","question":"Monthly salaries (₹ thousand) of seven employees in a team are 30, 32, 35, 38, 40, 42 and 250. Which figure best represents a typical salary, and why?","options":["₹250 thousand, the maximum, because it drives total cost","₹38 thousand, the median, because it is not pulled up by the 250 outlier","₹37.4 thousand, the mean without the top and bottom values","₹66.7 thousand, the mean, because it uses every value"],"answer":1,"explanation":"Mean = 467/7 ≈ 66.7, inflated by one very high salary; six of the seven earn less than that. The median (4th value) = 38 represents the typical employee.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-122","question":"Store A has mean daily sales of ₹50,000 with a standard deviation of ₹6,000. Store B has mean daily sales of ₹20,000 with a standard deviation of ₹3,000. Which store's sales are more consistent?","options":["Store A, because its coefficient of variation is 12% against B's 15%","Store B, because its coefficient of variation is 12%","Both are equally consistent","Store B, because its standard deviation is smaller"],"answer":0,"explanation":"Different means need a relative measure: CV = σ/mean. A: 6,000/50,000 = 12%; B: 3,000/20,000 = 15%. Lower CV = more consistent, so A. Comparing raw standard deviations favours B wrongly.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-123","question":"A distributor sold 200 units at ₹50, 300 units at ₹45 and 500 units at ₹40 during a quarter. What was the average selling price per unit?","options":["₹44","₹45","₹42","₹43.5"],"answer":3,"explanation":"Weighted average = (200×50 + 300×45 + 500×40) ÷ 1,000 = 43,500 ÷ 1,000 = ₹43.5. The simple average of the three prices (₹45) ignores that most units sold at ₹40.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-124","question":"Delivery times of a food app are normally distributed with mean 30 minutes and standard deviation 5 minutes. On a day with 1,200 orders, about how many take longer than 40 minutes?","options":["About 190","About 2","About 27","About 60"],"answer":2,"explanation":"z = (40 − 30)/5 = 2. P(Z > 2) ≈ 0.0228. Expected count = 1,200 × 0.0228 ≈ 27. 60 uses 5%, which is the share outside ±2σ on both sides; 190 uses z = 1.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-125","question":"A product needs parts from three independent suppliers, each delivering on time with probability 0.9. Production starts on time only if all three deliver on time. What is the probability that at least one delivery is late?","options":["0.100","0.271","0.001","0.300"],"answer":1,"explanation":"P(all on time) = 0.9³ = 0.729, so P(at least one late) = 1 − 0.729 = 0.271. Adding 0.1 three times (0.3) double-counts cases where two are late; 0.001 is the chance that all three are late.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-126","question":"1% of card transactions are fraudulent. A fraud model flags 95% of fraudulent transactions and also flags 4% of genuine ones. If a transaction is flagged, what is the probability that it is actually fraudulent?","options":["95.0%","96.0%","49.0%","19.3%"],"answer":3,"explanation":"P(flag) = 0.01 × 0.95 + 0.99 × 0.04 = 0.0095 + 0.0396 = 0.0491. P(fraud | flag) = 0.0095 ÷ 0.0491 ≈ 19.3%. The low base rate means most flags are false alarms; 95% is P(flag | fraud), not P(fraud | flag).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-127","question":"A machine produces 10% defectives, independently. In a random sample of 5 items, what is the probability of at most one defective?","options":["0.328","0.672","0.919","0.590"],"answer":2,"explanation":"P(0) = 0.9⁵ = 0.59049; P(1) = 5 × 0.1 × 0.9⁴ = 0.32805. P(≤ 1) = 0.91854 ≈ 0.919. 0.590 counts only zero defectives.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-128","question":"Calls reach a support line at an average of 3 per 10 minutes (Poisson). What is the probability of no calls in a 5-minute window?","options":["0.2231","0.7769","0.0498","0.5000"],"answer":0,"explanation":"For 5 minutes the mean is λ = 1.5. P(0) = e^(−1.5) = 0.2231. Using λ = 3 (the 10-minute rate) gives 0.0498; 0.7769 is P(at least one call).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-129","question":"A regression of monthly sales on advertising spend (both in ₹ lakh) gives Sales = 120 + 4.5 × AdSpend, with R² = 0.64. Which statements are correct?\nI. Each extra ₹1 lakh of advertising is associated with ₹4.5 lakh more sales.\nII. 64% of the variation in sales is explained by advertising spend.\nIII. The correlation coefficient between sales and advertising is 0.64.\nIV. With zero advertising the model predicts sales of ₹120 lakh.","options":["I and III only","II, III and IV only","I, II and IV only","I, II, III and IV"],"answer":2,"explanation":"The slope and intercept read as in I and IV, and R² is the share of variance explained (II). The correlation is r = +√0.64 = 0.8 (positive because the slope is positive), so III is false.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-130","question":"Weekly sales (y, ₹ lakh) for promotion budgets x = 1, 2, 3, 4, 5 (₹ lakh) were 3, 5, 4, 7 and 8. Using a least-squares line, what sales are predicted for a budget of 7?","options":["₹8.4 lakh","₹11.4 lakh","₹9.6 lakh","₹10.2 lakh"],"answer":3,"explanation":"x̄ = 3, ȳ = 5.4. Sxy = (−2)(−2.4) + (−1)(−0.4) + 0 + (1)(1.6) + (2)(2.6) = 12; Sxx = 10. b = 1.2; a = 5.4 − 1.2 × 3 = 1.8. ŷ(7) = 1.8 + 1.2 × 7 = 10.2. Leaving out the intercept gives 8.4.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-131","question":"In a simple regression of y on x, the slope is 2.5, the standard deviation of x is 4 and the standard deviation of y is 12.5. What is R²?","options":["0.64","0.80","0.40","0.96"],"answer":0,"explanation":"r = b × (σx/σy) = 2.5 × 4/12.5 = 0.8. In simple regression R² = r² = 0.64. 0.80 is r itself.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-132","question":"A salary model (₹ lakh per year) is Salary = 5 + 2.0 × Experience (years) + 4.0 × MBA, where MBA = 1 for an MBA and 0 otherwise. What is the predicted salary of an MBA with 3 years' experience minus that of a non-MBA with 5 years' experience?","options":["−₹4 lakh","₹0","₹8 lakh","₹4 lakh"],"answer":1,"explanation":"MBA, 3 years: 5 + 6 + 4 = 15. Non-MBA, 5 years: 5 + 10 + 0 = 15. Difference = 0: the MBA premium of 4 exactly offsets 2 fewer years at 2 per year.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-133","question":"A multiple regression with 4 predictors fitted on 25 observations has R² = 0.80. What is the adjusted R²?","options":["0.76","0.64","0.80","0.83"],"answer":0,"explanation":"Adjusted R² = 1 − (1 − R²)(n − 1)/(n − k − 1) = 1 − 0.2 × 24/20 = 0.76. Inverting the fraction gives 0.83, which would wrongly reward extra predictors.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-134","question":"A marketer tests H0: 'the new campaign does not increase average sales' against H1: 'it increases sales'. What is a Type I error here?","options":["Using a sample that is too small","Concluding the campaign does not increase sales when in fact it does","Concluding the campaign increases sales when in fact it does not","Rejecting H1 when H1 is false"],"answer":2,"explanation":"A Type I error is rejecting a true H0, so the firm believes in an effect that is not there (a false positive). The first distractor is a Type II error.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-135","question":"A two-tailed test of whether average basket size has changed gives a p-value of 0.032. Which conclusion is correct?","options":["There is a 3.2% probability that H0 is true","Do not reject H0 at the 5% level","Reject H0 at both the 5% and the 1% levels","Reject H0 at the 5% level but not at the 1% level"],"answer":3,"explanation":"Reject when p < α: 0.032 < 0.05 but 0.032 > 0.01. A p-value is the probability of data at least this extreme if H0 were true, not the probability that H0 is true.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-136","question":"A courier claims an average delivery time of 30 minutes. A sample of 64 deliveries has a mean of 31.5 minutes; the population standard deviation is known to be 6 minutes. For a two-tailed test at the 5% level, what is the test statistic and the decision?","options":["z = 2.0; do not reject H0 because 2.0 < 2.58","z = 2.0; reject H0","z = 16.0; reject H0","z = 0.25; do not reject H0"],"answer":1,"explanation":"Standard error = 6/√64 = 0.75. z = (31.5 − 30)/0.75 = 2. The 5% two-tailed critical value is 1.96, and 2.0 > 1.96, so reject H0. 2.58 is the 1% critical value; 0.25 forgets to divide by the standard error.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-137","question":"A survey must estimate the share of customers who would switch brands to within ±2 percentage points at 95% confidence. With no prior estimate (use p = 0.5), what is the minimum sample size?","options":["49","2,401","4,802","2,500"],"answer":1,"explanation":"n = z² p(1 − p)/E² = 1.96² × 0.25/0.02² = 0.9604/0.0004 = 2,401. Using z = 2 gives 2,500; using p(1 − p) = 0.5 gives 4,802; forgetting to square E gives 49.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-138","question":"A sample of 100 invoices has a mean processing time of 250 minutes with a standard deviation of 40 minutes. What is the 95% confidence interval for the mean processing time?","options":["249.22 to 250.78 minutes","171.60 to 328.40 minutes","243.42 to 256.58 minutes","242.16 to 257.84 minutes"],"answer":3,"explanation":"Standard error = 40/√100 = 4. CI = 250 ± 1.96 × 4 = 250 ± 7.84. Using σ instead of the standard error gives the much wider 171.60–328.40; 1.645 is the 90% multiplier.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-139","question":"H0: μ = 100 against H1: μ > 100, with σ = 10, n = 25 and α = 0.05. If the true mean is actually 105, what is the power of the test (approximately)?","options":["0.80","0.95","0.20","0.64"],"answer":0,"explanation":"SE = 10/5 = 2. Reject when x̄ > 100 + 1.645 × 2 = 103.29. If μ = 105: P(x̄ > 103.29) = P(Z > -0.855) ≈ 0.80. That is the power; β = 0.20 is the Type II error probability.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-140","question":"Assertion (A): With the sample size fixed, lowering the significance level from 5% to 1% raises the probability of a Type II error.\nReason (R): A smaller significance level moves the critical value closer to the hypothesised mean.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: a stricter α makes rejection harder, so false null hypotheses are kept more often (β rises). R is false: a smaller α moves the critical value further from the hypothesised mean (1.96 → 2.58 standard errors), widening the acceptance region.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-141","question":"Across 36 months, a retailer's ice-cream sales and air-conditioner sales have a correlation of 0.9. Which conclusion is most defensible?","options":["Ice-cream promotions will raise AC sales","The correlation proves the two products are complements","AC sales cause ice-cream sales","Both may be driven by a third factor such as temperature"],"answer":3,"explanation":"Correlation does not establish causation. A common driver (hot weather) can move both series together.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-142","question":"A sales pipeline has four deals: ₹10 lakh (win probability 0.5), ₹20 lakh (0.3), ₹5 lakh (0.9) and ₹40 lakh (0.1). What is the expected (probability-weighted) pipeline value?","options":["₹45 lakh","₹75 lakh","₹19.5 lakh","₹18.75 lakh"],"answer":2,"explanation":"Expected value = 5 + 6 + 4.5 + 4 = ₹19.5 lakh. ₹75 lakh is the unweighted total; ₹18.75 lakh is its simple average.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-143","question":"Two warehouses face independent daily demand with standard deviations of 30 and 40 units. Each holds safety stock of 2σ. If both are served from one central warehouse (same z, same lead time), how many units of safety stock are saved?","options":["20 units","40 units","70 units","0 units"],"answer":1,"explanation":"Separate: 2 × 30 + 2 × 40 = 140. Pooled σ = √(30² + 40²) = 50, so central safety stock = 2 × 50 = 100. Saving = 40 units. Variances add, standard deviations do not, which is the risk-pooling effect.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-144","question":"For a set of order values, Q1 = ₹40 and Q3 = ₹70 (in ₹ hundred). By the 1.5 × IQR rule, which value is an outlier?","options":["118","112","100","−4"],"answer":0,"explanation":"IQR = 30; fences = 40 − 45 = −5 and 70 + 45 = 115. Only 118 lies outside; 112 and −4 are just inside the fences.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-145","question":"Order values have mean ₹800 and standard deviation ₹300. What is the approximate probability that the average of a random sample of 36 orders exceeds ₹900?","options":["4.55%","2.28%","15.87%","36.94%"],"answer":1,"explanation":"By the central limit theorem, the sample mean has SE = 300/√36 = 50. z = (900 − 800)/50 = 2 → P ≈ 2.28%. 36.94% is the chance that a single order exceeds ₹900.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-146","question":"Team A converted 40 of 100 small-business leads and 10 of 100 enterprise leads. Team B converted 15 of 30 small-business leads and 30 of 170 enterprise leads. Which statement is correct?","options":["B is better in both segments and overall","A and B have the same overall conversion rate","A is better in both segments and overall","B has the higher rate in both segments but the lower overall rate, because most of its leads are enterprise leads"],"answer":3,"explanation":"Small business: A 40%, B 50%. Enterprise: A 10%, B 17.6%. Overall: A 50/200 = 25%, B 45/200 = 22.5%. B wins every segment yet loses overall because its leads are concentrated in the low-conversion segment (Simpson's paradox).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-147","question":"A shoe retailer wants to decide which single size to stock the most of. Which measure of the customers' shoe sizes is most useful?","options":["Mode","Mean","Range","Standard deviation"],"answer":0,"explanation":"The most frequently demanded size (the mode) is what matters; a mean size of, say, 7.6 may not even exist as a size.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-148","question":"Daily units sold over five days were 8, 10, 12, 14 and 16. What is the sample standard deviation?","options":["8.00","10.00","3.16","2.83"],"answer":2,"explanation":"Mean = 12; squared deviations 16, 4, 0, 4, 16 sum to 40. Sample variance = 40/(5 − 1) = 10, so s = √10 ≈ 3.16. Dividing by n gives the population value 2.83; 10 is the variance, not the standard deviation.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-149","question":"Of 400 surveyed customers: 90 saw the ad and purchased, 60 did not see it but purchased, 110 saw it but did not purchase, and 140 neither saw it nor purchased. What is the probability that a purchaser saw the ad?","options":["0.45","0.225","0.60","0.375"],"answer":2,"explanation":"Purchasers = 90 + 60 = 150, of whom 90 saw the ad: 90/150 = 0.60. 0.45 is P(purchase | saw ad) = 90/200; 0.225 is the joint probability 90/400.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-150","question":"In an A/B test, version A converts 200 of 2,000 visitors and version B converts 260 of 2,000. Using a pooled two-proportion z-test, two-tailed, which conclusion is correct?","options":["z ≈ 0.30; not significant","z ≈ 2.97; the difference is significant even at the 1% level","z ≈ 2.97; significant at 5% but not at 1%","z ≈ 1.50; not significant at 5%"],"answer":1,"explanation":"Pooled p = 460/4,000 = 0.115. SE = √[0.115 × 0.885 × (1/2,000 + 1/2,000)] = 0.01009. z = (0.13 − 0.10)/0.01009 ≈ 2.97 > 2.576, so it is significant at 1% (and at 5%).","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-151","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =SUMIFS(D2:D7, A2:A7, \"North\", C2:C7, \"Laptop\") return?","options":["270","150","365","330"],"answer":0,"explanation":"SUMIFS adds Sales only where both conditions hold: rows 2 (120) and 7 (150) = 270. 365 is all North sales; 330 is all Laptop sales.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-152","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =COUNTIFS(B2:B7, \"Asha\", D2:D7, \">60\") return?","options":["2","3","0","1"],"answer":3,"explanation":"Asha's rows have Sales 120, 60 and 45. Only 120 is strictly greater than 60, so the count is 1. Treating \">60\" as ≥ 60 gives 2.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-153","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =VLOOKUP(\"Asha\", B2:D7, 3, FALSE) return?","options":["#N/A","120","225","Laptop"],"answer":1,"explanation":"VLOOKUP searches the first column of B2:D7 (Rep) for an exact match and returns the first one it finds, row 2. Column 3 of B:D is Sales → 120. It does not add Asha's other rows (225); column 2 would give 'Laptop'.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-154","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =VLOOKUP(\"Ravi\", A2:D7, 2, FALSE) return?","options":["80","South","Ravi","#N/A"],"answer":3,"explanation":"VLOOKUP always searches the first column of the table array, here column A (Region). 'Ravi' never appears in column A, so an exact-match lookup returns #N/A.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-155","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =INDEX(A2:A7, MATCH(MAX(D2:D7), D2:D7, 0)) return?","options":["North","Laptop","Ravi","6"],"answer":0,"explanation":"MAX(D2:D7) = 150. MATCH finds it at position 6 of D2:D7. INDEX(A2:A7, 6) returns the 6th Region, North. MATCH alone would return 6; Ravi is in column B, not A.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-156","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =SUMPRODUCT((A2:A7=\"North\")+(C2:C7=\"Laptop\"), D2:D7) return?","options":["425","365","695","270"],"answer":2,"explanation":"Adding the two TRUE/FALSE arrays gives 2 for rows that are both North and Laptop (rows 2 and 7), 1 for rows meeting one condition (rows 4 and 5), 0 otherwise. Sum = 2×120 + 95 + 60 + 2×150 = 695. Rows meeting both conditions are counted twice, so this is not a true OR (425); multiplying the arrays would give the AND total, 270.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-157","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =AVERAGEIF(A2:A7, \"North\", D2:D7) return (to two decimals)?","options":["91.67","121.67","365.00","110.00"],"answer":1,"explanation":"North rows: 120, 95, 150 → sum 365 over 3 rows = 121.67. 91.67 averages every row; 110 is the Laptop average.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-158","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =XLOOKUP(\"Asha\", B2:B7, D2:D7, \"None\", 0, -1) return?","options":["45","225","None","120"],"answer":0,"explanation":"The last argument −1 makes XLOOKUP search from the bottom up, so it finds Asha's last row (row 6) and returns its Sales, 45. A normal top-down search returns 120; 'None' would appear only if Asha were missing.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-159","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. A pivot table puts Rep in Rows and 'Average of Sales' in Values, sorted largest to smallest. Which rep appears first?","options":["Asha (3)","Asha (75)","Meena (95)","Ravi (115)"],"answer":3,"explanation":"Averages: Asha (120 + 60 + 45)/3 = 75; Ravi (80 + 150)/2 = 115; Meena 95. Ravi is first. Asha would lead only if the value field were Count of Sales (3 rows).","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-160","question":"Cell C2 contains =A2*$B$1. It is copied to cell D5. What formula does D5 contain?","options":["=B2*$B$1","=B5*$C$1","=B5*$B$1","=A5*$B$1"],"answer":2,"explanation":"Copying from C2 to D5 moves one column right and three rows down. The relative reference A2 becomes B5; the absolute $B$1 does not change.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-161","question":"Cell E3 contains =$A3+B$2. It is copied to cell G6. What formula does G6 contain?","options":["=$A3+D$2","=$C6+D$2","=$A6+D$2","=$A6+D$5"],"answer":2,"explanation":"The move is +2 columns and +3 rows. In $A3 the column is locked and the row moves: $A6. In B$2 the row is locked and the column moves: D$2.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-162","question":"A2:A6 hold 1, 2, 3, 4, 5 and B1:F1 hold 1, 2, 3, 4, 5. Cell B2 contains =$A2*B$1, and it is filled across and down to F6. What value appears in D5?","options":["15","20","16","12"],"answer":3,"explanation":"D5 holds =$A5*D$1. A5 = 4 (A2 = 1, so A5 is the fourth value) and D1 = 3 (B1 = 1, C1 = 2, D1 = 3). 4 × 3 = 12. Reading A5 as 5 and D1 as 4 gives 20.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-163","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. Column E uses =IF(D2>=100, \"High\", IF(D2>=60, \"Medium\", \"Low\")), filled down to E7. How many rows show \"Medium\"?","options":["2","3","1","4"],"answer":1,"explanation":"Labels: 120 High, 80 Medium, 95 Medium, 60 Medium (60 ≥ 60), 45 Low, 150 High → 3 Medium. Treating ≥ 60 as > 60 drops row 5 and gives 2.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-164","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. Column F uses =IF(AND(A2=\"North\", D2>100), \"Bonus\", IF(OR(C2=\"Phone\", D2<50), \"Review\", \"-\")), filled down. How many rows show \"Review\"?","options":["3","4","2","1"],"answer":0,"explanation":"Row 2 Bonus; row 3 Phone → Review; row 4 North but 95 ≤ 100, Phone → Review; row 5 '-'; row 6 45 < 50 → Review; row 7 Bonus. 3 rows show Review. Row 4 is the trap: it fails the Bonus test and falls through to the second IF.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-165","question":"Commission slabs are in F2:G5: F = 0, 50000, 100000, 200000 and G = 0%, 2%, 5%, 8% (sorted ascending). A rep's sales of ₹150,000 are in A1. What does =A1*VLOOKUP(A1, F2:G5, 2, TRUE) return?","options":["#N/A","3,000","12,000","7,500"],"answer":3,"explanation":"With TRUE (approximate match) VLOOKUP returns the row with the largest F value ≤ 150,000, which is 100,000 → 5%. Commission = 150,000 × 5% = 7,500. 8% would need sales of 200,000 or more; an exact match would give #N/A.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-166","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =COUNTIF(D2:D7, \">\"&AVERAGE(D2:D7)) return?","options":["2","0","3","4"],"answer":2,"explanation":"AVERAGE(D2:D7) = 550/6 ≈ 91.67; the & builds the criterion \">91.67\". Values above it: 120, 95, 150 → 3.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-167","question":"What does =LEFT(\"INV-2026-0457\", 3) & \"/\" & RIGHT(\"INV-2026-0457\", 4) return?","options":["INV/2026","INV/0457","INV-/0457","INV/457"],"answer":1,"explanation":"LEFT(…, 3) takes 'INV' and RIGHT(…, 4) takes '0457' (the leading zero is kept because the value is text). & joins them with '/': INV/0457.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-168","question":"A sheet has headers in A1:D1 (Region, Rep, Product, Sales) and data in rows 2–7: row 2: North, Asha, Laptop, 120; row 3: South, Ravi, Phone, 80; row 4: North, Meena, Phone, 95; row 5: East, Asha, Laptop, 60; row 6: South, Asha, Tablet, 45; row 7: North, Ravi, Laptop, 150. What does =IFERROR(VLOOKUP(\"Kiran\", B2:D7, 3, FALSE), 0) + SUMIF(B2:B7, \"Ravi\", D2:D7) return?","options":["230","#N/A","80","150"],"answer":0,"explanation":"Kiran is not in column B, so VLOOKUP gives #N/A, which IFERROR turns into 0. SUMIF adds Ravi's Sales: 80 + 150 = 230. Total = 230.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-169","question":"Which Excel function counts the cells in a range that are not empty, whether they hold numbers or text?","options":["COUNTA","COUNTIF","COUNTBLANK","COUNT"],"answer":0,"explanation":"COUNTA counts every non-empty cell; COUNT counts only numeric cells; COUNTBLANK counts empty cells.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-170","question":"A1:A7 contain: 12; the text NA; 0; 7.5; an empty cell; the logical value TRUE; and '15 (a number stored as text). What does =COUNTA(A1:A7) − COUNT(A1:A7) return?","options":["1","2","4","3"],"answer":3,"explanation":"COUNT counts numeric cells only: 12, 0 and 7.5 → 3 (TRUE in a range and the text '15' are not counted). COUNTA counts all non-empty cells: 6. 6 − 3 = 3.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-171","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT COUNT(*) FROM orders WHERE region = 'North'; return?","options":["2","7","3","4"],"answer":2,"explanation":"Rows 1, 3 and 6 are North, so COUNT(*) returns 3.","difficulty":"easy","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-172","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT COUNT(amount) FROM orders; return?","options":["5","6","0","7"],"answer":1,"explanation":"COUNT(column) skips NULLs. Order 4 has a NULL amount, so the result is 6; COUNT(*) would return 7.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-173","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT AVG(amount) FROM orders WHERE region = 'East'; return?","options":["175","0","350","NULL"],"answer":2,"explanation":"East has orders 4 (NULL) and 7 (350). AVG ignores NULLs, so it averages one value: 350. Treating NULL as 0 would give 175.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-174","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Which customers does SELECT customer, SUM(amount) FROM orders GROUP BY customer HAVING SUM(amount) > 600; return?","options":["Ravi (700) only","Asha (700) and Ravi (1000)","Asha (700), Ravi (1000) and John (400)","Ravi (1000) only"],"answer":1,"explanation":"Totals: Asha 500 + 200 = 700; Ravi 300 + 700 = 1,000; Meena 350 (NULL ignored); John 400. HAVING keeps groups whose total exceeds 600: Asha and Ravi. 'Ravi (700) only' is what a row-level filter (WHERE amount > 600) would give.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-175","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What does SELECT region, COUNT(*) FROM orders WHERE amount > 250 GROUP BY region HAVING COUNT(*) >= 2; return?","options":["North 2, South 2 and East 1","North 3 and South 2","South 2 only","North 2 and South 2"],"answer":3,"explanation":"WHERE runs first and keeps amounts above 250: orders 1 (N), 2 (S), 5 (S), 6 (N) and 7 (E); order 3 (200) and the NULL fail. Groups: North 2, South 2, East 1. HAVING COUNT(*) ≥ 2 drops East. North 3 counts order 3, which WHERE has already removed.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-176","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Table customers(name, tier) has 4 rows: (Asha, Gold), (Ravi, Silver), (Kiran, Gold), (John, Bronze). What does SELECT c.name, COUNT(o.order_id) FROM customers c LEFT JOIN orders o ON c.name = o.customer GROUP BY c.name; return?","options":["4 rows, with Kiran showing 0","5 rows, including Meena with 2","3 rows; Kiran does not appear","4 rows, with Kiran showing 1"],"answer":0,"explanation":"A LEFT JOIN keeps every customer. Kiran has no orders, so the joined row has NULL order_id, and COUNT(o.order_id) gives 0 (COUNT(*) would wrongly give 1). Meena is not in customers, so she does not appear. Result: Asha 2, Ravi 2, Kiran 0, John 1.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-177","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Table customers(name, tier) has 4 rows: (Asha, Gold), (Ravi, Silver), (Kiran, Gold), (John, Bronze). How many rows does SELECT * FROM customers c INNER JOIN orders o ON c.name = o.customer; return?","options":["7","4","5","28"],"answer":2,"explanation":"An inner join keeps only matching pairs: Asha 2 orders, Ravi 2, John 1 = 5. Kiran has no orders and Meena is not a customer, so neither appears. 28 = 4 × 7 is the cross join.","difficulty":"hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-178","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). Which orders does SELECT order_id FROM orders WHERE amount IS NOT NULL ORDER BY amount DESC LIMIT 2 OFFSET 1; return?","options":["Orders 5 and 1","Orders 1, 6 and 7","Orders 6 and 7","Orders 1 and 6"],"answer":3,"explanation":"Sorted by amount, highest first: 5 (700), 1 (500), 6 (400), 7 (350), 2 (300), 3 (200). OFFSET 1 skips order 5, and LIMIT 2 returns the next two: orders 1 and 6.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-179","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). What happens when SELECT region, SUM(amount) FROM orders WHERE SUM(amount) > 500 GROUP BY region; is run?","options":["It raises an error, because aggregate functions cannot be used in WHERE","It returns all three regions","It returns North only","It returns North and South"],"answer":0,"explanation":"WHERE filters individual rows before grouping, so it cannot refer to SUM(). The condition belongs in HAVING: … GROUP BY region HAVING SUM(amount) > 500.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-180","question":"Table orders(order_id, customer, region, amount) has 7 rows: (1, Asha, North, 500); (2, Ravi, South, 300); (3, Asha, North, 200); (4, Meena, East, NULL); (5, Ravi, South, 700); (6, John, North, 400); (7, Meena, East, 350). How many rows does SELECT order_id FROM orders WHERE amount < (SELECT AVG(amount) FROM orders); return?","options":["3","4","2","5"],"answer":1,"explanation":"AVG ignores the NULL: 2,450/6 ≈ 408.33. Amounts below it: 300, 200, 350 and 400 → 4 rows. The NULL row is never returned, because NULL < x is unknown, not true. Treating NULL as 0 would make the average 350 and give only 2 rows.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-181","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. In which quarter was the gross margin percentage highest?","options":["Q4","Q3","Q2","Q1"],"answer":2,"explanation":"Gross margin = (revenue − COGS)/revenue: Q1 90/240 = 37.5%; Q2 105/270 = 38.9%; Q3 114/300 = 38.0%; Q4 120/330 = 36.4%. Q4 has the largest gross profit in rupees but the lowest percentage.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-182","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. By what percentage did operating profit grow from Q1 to Q4?","options":["29.8%","37.5%","17.0%","42.5%"],"answer":3,"explanation":"Operating profit = revenue − COGS − opex: Q1 = 240 − 150 − 50 = 40; Q4 = 330 − 210 − 63 = 57. Growth = 17/40 = 42.5%. 37.5% is revenue growth; 29.8% divides by the Q4 figure.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-183","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. Revenue grew 37.5% from Q1 to Q4. How does this split into volume growth and growth in average realised price per unit?","options":["Volume +25%, price +10%","Volume +12.5%, price +25%","Volume +25%, price +12.5%","Volume +20%, price +15%"],"answer":0,"explanation":"Average price = revenue ÷ units: Q1 = 240 crore ÷ 4.8 lakh = ₹5,000; Q4 = 330 ÷ 6.0 = ₹5,500, i.e. +10%. Volume: 6.0/4.8 = +25%. The effects multiply: 1.25 × 1.10 = 1.375. Subtracting 25 from 37.5 to get a 12.5% price rise treats the growth rates as additive.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-184","question":"A consumer-electronics firm's quarterly figures (₹ crore unless stated), Q1 to Q4: revenue 240, 270, 300, 330; cost of goods sold 150, 165, 186, 210; operating expenses 50, 54, 57, 63; units sold (lakh) 4.8, 5.2, 5.6, 6.0. Treat COGS as fully variable and operating expenses as fully fixed. At Q4's cost structure, what quarterly revenue is needed to break even?","options":["₹99.00 crore","₹173.25 crore","₹157.50 crore","₹273.00 crore"],"answer":1,"explanation":"Contribution margin ratio = (330 − 210)/330 = 0.3636. Break-even revenue = fixed costs ÷ CM ratio = 63 ÷ 0.3636 = ₹173.25 crore. Dividing by the variable-cost ratio instead gives ₹99.00 crore; 273 just adds COGS and opex.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-185","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What is the network's overall on-time delivery rate?","options":["91.00%","93.00%","92.50%","92.67%"],"answer":2,"explanation":"On-time orders = 11,280 + 8,370 + 13,650 = 33,300 out of 36,000 → 92.50%. The simple average of 94%, 93% and 91% (92.67%) ignores that W3, the weakest, ships the most.","difficulty":"moderate","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-186","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What is the inventory turnover of the network as a whole?","options":["15.00","12.00","9.00","11.16"],"answer":3,"explanation":"Network turns = total COGS ÷ total inventory = 2,790 ÷ 250 = 11.16. Averaging the three warehouse turns (12, 15, 9) gives 12, which over-weights the small, fast W2.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-187","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. If W3 raises its own inventory turnover to 12 while handling the same COGS, what will network turnover become?","options":["12.00","12.68","13.00","11.16"],"answer":1,"explanation":"W3's inventory falls to 1,080/12 = ₹90 lakh, so network inventory = 80 + 50 + 90 = ₹220 lakh. Turns = 2,790/220 = 12.68. Averaging 12, 15 and 12 gives 13, which is not how a network ratio is formed.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-188","question":"A distributor's three warehouses last year: W1 shipped 12,000 orders (11,280 on time), held average inventory of ₹80 lakh and handled COGS of ₹960 lakh; W2 shipped 9,000 (8,370 on time), inventory ₹50 lakh, COGS ₹750 lakh; W3 shipped 15,000 (13,650 on time), inventory ₹120 lakh, COGS ₹1,080 lakh. What share of the network's late orders comes from W3?","options":["50.0%","41.7%","33.3%","26.7%"],"answer":0,"explanation":"Late orders: W1 720, W2 630, W3 1,350; total 2,700. W3's share = 1,350/2,700 = 50.0%. 41.7% is W3's share of all shipments.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-189","question":"A product market was worth ₹800 crore in 2025 and ₹920 crore in 2026. Market shares in 2025: brand A 30%, B 25%, C 20%, others 25%. In 2026: A 28%, B 27%, C 22%, others 23%. By what percentage did brand A's revenue change from 2025 to 2026?","options":["Rose 15.00%","Rose 7.33%","Fell 6.67%","Fell 2.00%"],"answer":1,"explanation":"A's revenue: 0.30 × 800 = ₹240 crore → 0.28 × 920 = ₹257.6 crore, a rise of 7.33%. Its share fell 2 points (6.67% in relative terms), but the 15% market growth more than offset it.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-190","question":"A product market was worth ₹800 crore in 2025 and ₹920 crore in 2026. Market shares in 2025: brand A 30%, B 25%, C 20%, others 25%. In 2026: A 28%, B 27%, C 22%, others 23%. By what percentage did the combined revenue of 'others' change from 2025 to 2026?","options":["Fell 2.0%","Rose 15.0%","Rose 5.8%","Fell 8.0%"],"answer":2,"explanation":"Others: 0.25 × 800 = ₹200 crore → 0.23 × 920 = ₹211.6 crore, so revenue rose 5.8% (1.15 × 0.23/0.25 = 1.058). The 8% figure is the relative fall in share, which is not the same as a fall in revenue.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-191","question":"Assertion (A): A rise in the holding cost per unit raises the economic order quantity.\nReason (R): Annual holding cost increases as the order quantity increases.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: EOQ = √(2DS/H), so a higher H lowers EOQ (order smaller lots more often). R is true: annual holding cost = QH/2 rises with Q, which is exactly why a higher H pushes the optimum down.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-192","question":"Assertion (A): A higher smoothing constant α makes an exponential-smoothing forecast smoother.\nReason (R): A higher α puts more weight on the most recent demand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: a higher α reacts faster and follows random noise more closely, so the forecast is less smooth. R is true: F(t+1) = αA(t) + (1 − α)F(t).","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-193","question":"Assertion (A): In an M/M/1 queue, raising utilisation from 80% to 90% more than doubles the average number waiting in the queue.\nReason (R): Lq = ρ²/(1 − ρ), which grows without bound as ρ approaches 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"At ρ = 0.8, Lq = 0.64/0.2 = 3.2; at ρ = 0.9, Lq = 0.81/0.1 = 8.1, about 2.53 times as many. A is true and follows from R: the 1 − ρ denominator shrinks fast near full utilisation.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-194","question":"Assertion (A): A Six Sigma process produces about 3.4 defects per million opportunities.\nReason (R): Six Sigma improvement projects follow the DMAIC cycle.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both statements are true, but DMAIC is the project method; it does not explain why six sigma corresponds to 3.4 DPMO. That figure comes from a 4.5σ one-sided tail after allowing a 1.5σ drift of the mean.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-195","question":"Assertion (A): For household income data, the median is usually a better measure of the typical value than the mean.\nReason (R): For any data set, the median equals the mode.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true: income is right-skewed, and a few very high incomes pull the mean up. R is false: the median and mode coincide only for some (for example symmetric unimodal) distributions.","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-196","question":"A bottleneck machine has 2,400 minutes a month. Product X earns a contribution of ₹60 and needs 6 bottleneck minutes; Y earns ₹40 and needs 3 minutes; Z earns ₹90 and needs 10 minutes. Monthly demand is 200 X, 300 Y and 150 Z. What is the maximum monthly contribution?","options":["₹26,700","₹37,500","₹22,500","₹24,000"],"answer":0,"explanation":"Rank by contribution per bottleneck minute: Y 40/3 = 13.33, X 60/6 = 10, Z 90/10 = 9. Make all 300 Y (900 min) and all 200 X (1,200 min); the remaining 300 min make 30 Z. Contribution = 12,000 + 12,000 + 2,700 = ₹26,700. Ranking by contribution per unit (Z first) gives only ₹22,500; ₹37,500 ignores the capacity limit.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-197","question":"An e-commerce firm receives 600 returns a day, and each pending return carries an average refund of ₹1,500 owed to the customer. A return currently takes 4 days from receipt to refund. If this is cut to 2.5 days, by how much does the average value of pending refunds fall?","options":["₹22.5 lakh","₹9 lakh","₹13.5 lakh","₹36 lakh"],"answer":2,"explanation":"Little's law: pending returns = 600 × 4 = 2,400 now and 600 × 2.5 = 1,500 after, a fall of 900. Value = 900 × ₹1,500 = ₹13.5 lakh. ₹22.5 lakh is the new level, not the reduction.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-198","question":"A buyer scores three vendors out of 10 on cost (weight 40%), quality (35%) and delivery (25%). V1: 8, 6, 9. V2: 6, 9, 7. V3: 7, 8, 8. Which vendor has the highest weighted score?","options":["V2, 7.30","V3, 7.60","V1, 7.55","V1, 7.67"],"answer":1,"explanation":"Weighted scores: V1 = 3.2 + 2.1 + 2.25 = 7.55; V2 = 2.4 + 3.15 + 1.75 = 7.30; V3 = 2.8 + 2.8 + 2.0 = 7.60. V3 wins narrowly. Unweighted averages tie V1 and V3 at 7.67.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-199","question":"Which supply-chain metric is calculated as 365 ÷ annual inventory turnover?","options":["Days of inventory on hand","Perfect-order rate","Days sales outstanding","Order fill rate"],"answer":0,"explanation":"365 ÷ (COGS/average inventory) converts turnover into the number of days the average stock would last. Days sales outstanding uses receivables and sales instead.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-200","question":"A firm has days inventory outstanding of 45, days sales outstanding of 30 and days payables outstanding of 50. If it cuts inventory by 5 days and negotiates 10 more days of credit from suppliers, what is its new cash-to-cash cycle?","options":["130 days","20 days","40 days","10 days"],"answer":3,"explanation":"Cash-to-cash = DIO + DSO − DPO = 45 + 30 − 50 = 25 days now. New = 40 + 30 − 60 = 10 days. Adding payables instead of subtracting them leads to figures like 130.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-201","question":"A firm compares two plant sites on four factors with weights: labour cost 0.30, proximity to market 0.25, infrastructure 0.25 and tax incentives 0.20. Scores out of 100 — Nashik: 70, 85, 60, 80; Hosur: 80, 65, 75, 70. Using the factor-rating method, which site wins and with what weighted score?","options":["Nashik, 73.25","Hosur, 73.00","Hosur, 72.50","Nashik, 73.75"],"answer":0,"explanation":"Nashik = 0.30×70 + 0.25×85 + 0.25×60 + 0.20×80 = 21 + 21.25 + 15 + 16 = 73.25. Hosur = 24 + 16.25 + 18.75 + 14 = 73.00. The margin is only 0.25 points, so a small change in any weight could flip the decision.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-202","question":"A distributor ships 300 tonnes a year to market A at grid point (20, 40), 500 tonnes to market B at (60, 10) and 200 tonnes to market C at (80, 70). Where is the centre of gravity for its new warehouse?","options":["(53.3, 40)","(52, 31)","(31, 52)","(56, 38)"],"answer":1,"explanation":"X = (20×300 + 60×500 + 80×200) ÷ 1,000 = 52,000 ÷ 1,000 = 52. Y = (40×300 + 10×500 + 70×200) ÷ 1,000 = 31,000 ÷ 1,000 = 31. A plain average of the coordinates, ignoring volumes, gives (53.3, 40); swapping the axes gives (31, 52).","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-203","question":"Four stores receive these monthly shipments: S1 at (10, 50) gets 400, S2 at (40, 20) gets 250, S3 at (70, 60) gets 350 and S4 at (90, 10) gets 200. The firm will pick the available site closest (straight-line) to the centre of gravity. Available sites: P (45, 40), Q (55, 35), R (35, 30), S (50, 25). Which site is chosen?","options":["Q","R","P","S"],"answer":2,"explanation":"Centre of gravity: X = (4,000 + 10,000 + 24,500 + 18,000) ÷ 1,200 = 47.08; Y = (20,000 + 5,000 + 21,000 + 2,000) ÷ 1,200 = 40. Distances: P ≈ 2.1, Q ≈ 9.4, R ≈ 15.7, S ≈ 15.3, so P is nearest. Ignoring shipment volumes gives the centre (52.5, 35), which would wrongly point to Q.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-204","question":"Three candidate locations have these annual fixed costs and variable costs per unit — A: ₹30 lakh and ₹750; B: ₹50 lakh and ₹500; C: ₹80 lakh and ₹300. Over what range of annual volume is location B the lowest-cost choice?","options":["8,000 to 11,111 units","11,111 to 15,000 units","Above 15,000 units","8,000 to 15,000 units"],"answer":3,"explanation":"A = B when 30L + 750Q = 50L + 500Q → Q = 20L ÷ 250 = 8,000. B = C when 50L + 500Q = 80L + 300Q → Q = 30L ÷ 200 = 15,000. Below 8,000 A is cheapest, between 8,000 and 15,000 B is cheapest, and above 15,000 C wins. The A–C crossover (≈ 11,111) is irrelevant because B is cheaper than both there.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-205","question":"Locations A, B and C have annual fixed costs of ₹30 lakh, ₹50 lakh and ₹80 lakh and variable costs of ₹750, ₹500 and ₹300 per unit. Expected volume is 12,000 units a year. Which location should be chosen and what is its total annual cost?","options":["C, ₹116 lakh","A, ₹120 lakh","B, ₹110 lakh","C, ₹110 lakh"],"answer":2,"explanation":"Total cost = fixed + variable × 12,000. A = 30 + 90 = ₹120 lakh; B = 50 + 60 = ₹110 lakh; C = 80 + 36 = ₹116 lakh. B is cheapest. Choosing C because it has the lowest variable cost ignores its much larger fixed cost at this volume.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-206","question":"Quarterly demand is 1,400, 2,000, 1,800 and 2,000 units. Each worker makes 100 units a quarter and the firm starts with 15 workers. Hiring costs ₹3,000 per worker, a layoff ₹5,000 per worker, and holding ₹50 per unit per quarter on ending inventory. Plan 1 (chase) matches output to demand each quarter. Plan 2 (level) sets one constant workforce from Q1 that meets total demand with no shortages. Regular wages are the same in both plans. Which plan is cheaper, and by how much?","options":["Chase, by ₹10,000","Level, by ₹10,000","Chase, by ₹1,000","Level, by ₹6,000"],"answer":0,"explanation":"Chase: workers needed 14, 20, 18, 20 → lay off 1, hire 6, lay off 2, hire 2. Cost = 8 × 3,000 + 3 × 5,000 = ₹39,000. Level: 7,200 ÷ 4 = 1,800 a quarter = 18 workers (hire 3 = ₹9,000). Ending inventory 400, 200, 200, 0 → 800 × 50 = ₹40,000. Level total = ₹49,000, so chase is cheaper by ₹10,000. Forgetting the level plan's hiring cost shrinks the gap to ₹1,000. Both plans use 72 worker-quarters, so wages cancel.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-207","question":"A firm produces at a constant rate equal to average demand. Quarterly demand is 1,000, 1,400, 1,600 and 1,200 units, and there is no opening stock. Ending inventory costs ₹40 per unit per quarter and each unit backordered at quarter-end costs ₹100 per quarter. What is the total inventory-plus-backorder cost for the year?","options":["₹20,000","₹24,000","₹40,000","₹30,000"],"answer":3,"explanation":"Output = 5,200 ÷ 4 = 1300 a quarter. Ending position: Q1 +300, Q2 +200, Q3 −100 (backorder), Q4 0. Holding = (300 + 200) × 40 = ₹20,000; backorder = 100 × 100 = ₹10,000; total ₹30,000. Ignoring the backorder gives ₹20,000; charging the shortage at the holding rate gives ₹24,000.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-208","question":"For one week, an item's gross requirement is 120 units. On-hand stock is 35, a scheduled receipt of 25 is due that week, and the firm keeps safety stock of 10. What is the net requirement?","options":["60","70","50","95"],"answer":1,"explanation":"Net requirement = gross − on hand − scheduled receipts + safety stock = 120 − 35 − 25 + 10 = 70. Leaving out safety stock gives 60, subtracting it gives 50, and forgetting the scheduled receipt gives 95.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-209","question":"Product A needs 2 units of B and 3 units of C. Each B needs 2 units of D; each C needs 1 unit of D and 4 units of E. An order for 50 A arrives. On hand: 20 B, 0 C and 30 D. What is the net requirement of D?","options":["320","280","310","350"],"answer":1,"explanation":"Net B = 2 × 50 − 20 = 80; net C = 3 × 50 = 150. Gross D = 2 × 80 + 1 × 150 = 310; net D = 310 − 30 = 280. Ignoring the B on hand gives gross D of 350 and net 320; forgetting the D on hand leaves 310.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-210","question":"Each unit of X needs 2 Y and 1 Z. Each Y needs 3 W. Each Z needs 2 W and 1 Y. With no stock on hand, how many units of W are needed for 40 units of X?","options":["320","400","480","440"],"answer":3,"explanation":"Y appears twice: 2 per X directly plus 1 inside each Z, so Y = 80 + 40 = 120. W = 3 × 120 (from Y) + 2 × 40 (from Z) = 360 + 80 = 440. Missing the Y inside Z gives 3 × 80 + 80 = 320.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-211","question":"Net requirements over six weeks are 50, 60, 70, 60, 95 and 75 units. Setup cost is ₹200 per order and holding cost is ₹1 per unit per week, charged on ending inventory. Orders arrive at the start of the week they are needed. Using a periodic order quantity that covers two weeks per order, what is the total cost over the six weeks?","options":["₹795","₹1,200","₹845","₹600"],"answer":0,"explanation":"Orders: week 1 (50 + 60 = 110), week 3 (70 + 60 = 130), week 5 (95 + 75 = 170). Ending inventory is 60 after weeks 1, 3 and 75 after week 5 (zero otherwise) → holding = 60 + 60 + 75 = ₹195. Setups = 3 × 200 = ₹600. Total ₹795. Lot-for-lot costs 6 × 200 = ₹1,200; a three-week POQ costs ₹845.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-212","question":"An item has gross requirements of 40, 0, 60, 30, 0 and 80 units in weeks 1–6. On-hand stock is 50, a scheduled receipt of 20 arrives in week 3, the lot size is a fixed 50 units (more lots if needed), lead time is 2 weeks and safety stock is zero. What are the planned order releases, and what is the projected on-hand at the end of week 6?","options":["Weeks 3, 4 and 6 (50 each); 10 units","Weeks 1, 2 and 4 (50, 50, 100); 40 units","Weeks 1, 2 and 4 (50 each); 10 units","Weeks 2, 3 and 5 (50 each); 10 units"],"answer":2,"explanation":"Projected on-hand: wk1 10, wk2 10, wk3 10 + 20 − 60 = −30 → receive 50 → 20, wk4 20 − 30 = −10 → receive 50 → 40, wk5 40, wk6 40 − 80 = −40 → receive 50 → 10. Planned receipts in weeks 3, 4, 6 are released 2 weeks earlier: weeks 1, 2, 4. Ignoring the scheduled receipt forces 100 in week 6 and leaves 40; listing the receipt weeks forgets the lead-time offset.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-213","question":"Five jobs go through machine M1 then M2. Times (hours) on M1, M2: A 5, 2; B 1, 6; C 9, 7; D 3, 8; E 10, 4. What sequence does Johnson's rule give?","options":["A–E–C–D–B","B–D–E–C–A","B–A–D–C–E","B–D–C–E–A"],"answer":3,"explanation":"Pick the smallest remaining time: B's 1 (on M1) → first; A's 2 (on M2) → last; D's 3 (M1) → second; E's 4 (M2) → second last; C fills the middle. Sequence B–D–C–E–A.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-214","question":"Five jobs go through machine M1 then M2. Times (hours) on M1, M2: A 5, 2; B 1, 6; C 9, 7; D 3, 8; E 10, 4. Using the Johnson sequence, what is the makespan and by how many hours does it beat processing the jobs in the order A–B–C–D–E?","options":["34 hours; 4 hours shorter","30 hours; 3 hours shorter","30 hours; 4 hours shorter","28 hours; 6 hours shorter"],"answer":2,"explanation":"Sequence B–D–C–E–A. M1 finishes at 1, 4, 13, 23, 28. M2: B 1–7, D 7–15, C 15–22, E 23–27, A 28–30 → makespan 30. In order A–B–C–D–E, M1 ends 5, 6, 15, 18, 28 and M2: 5–7, 7–13, 15–22, 22–30, 30–34 → 34. Saving = 4 hours. (M2 idles 3 hours under Johnson — that is not the saving.)","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-215","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). What is the average flow time under the SPT rule?","options":["13.6 days","13 days","5.6 days","28 days"],"answer":1,"explanation":"SPT order Q, S, P, R, T: completions 2, 5, 11, 19, 28. Average flow time = 65 ÷ 5 = 13 days. EDD (Q, P, S, R, T) gives 13.6; 5.6 is the mean processing time and 28 is the makespan.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-216","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). Compare SPT and EDD. Which statements are correct?\nI. SPT gives the lower average flow time.\nII. EDD gives the lower total tardiness.\nIII. Both rules give the same makespan.\nIV. EDD leaves no job tardy.","options":["I, II and III only","I and II only","I, III and IV only","II, III and IV only"],"answer":0,"explanation":"SPT (Q, S, P, R, T): completions 2, 5, 11, 19, 28 → flow 13.0, tardiness 0, 0, 1, 1, 5 = 7 (3 tardy jobs). EDD (Q, P, S, R, T): completions 2, 8, 11, 19, 28 → flow 13.6, tardiness 0, 0, 0, 1, 5 = 6 (2 tardy jobs). Makespan is 28 for any order. IV fails because R and T are still late.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-217","question":"Five jobs wait at one machine (processing days; due day, all available now): P 6 (10), Q 2 (6), R 8 (18), S 3 (15), T 9 (23). Using Moore–Hodgson's algorithm to minimise the number of tardy jobs, what is the minimum number of tardy jobs and which job is pushed to the end?","options":["1; job R","2; jobs R and T","0; no job","1; job T"],"answer":0,"explanation":"Start with EDD: Q, P, S, R, T → completions 2, 8, 11, 19, 28. The first tardy job is R (19 > 18). Remove the longest job so far (R, 8 days) and put it at the end. New schedule Q, P, S, T, R → completions 2, 8, 11, 20, 28: only R is late. Zero is impossible: Q, P, S and R are all due by day 18 but need 19 days of work together, so at least one of them must be late. Hence 1 is the minimum.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-218","question":"Four jobs pass through M1, M2 and M3 in that order. Times (hours): J1 8, 3, 6; J2 5, 4, 7; J3 6, 2, 5; J4 7, 5, 9. Using Johnson's rule extended to three machines (check its condition first), what are the sequence and the makespan?","options":["J2–J4–J1–J3; 40 hours","J2–J4–J1–J3; 37 hours","J3–J2–J4–J1; 37 hours","J1–J2–J3–J4; 40 hours"],"answer":1,"explanation":"Condition: min M1 time (5) ≥ max M2 time (5), so the method applies. Form G = M1 + M2 and H = M2 + M3: J1 (11, 9), J2 (9, 11), J3 (8, 7), J4 (12, 14). Johnson on (G, H): J3's 7 (H) → last; J2's 9 (G) → first; J1's 9 (H) → second last; J4 in the middle → J2–J4–J1–J3. Simulating: M3 completes at 37 hours (no order does better). The natural order J1–J4 takes 40 hours.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-219","question":"Today is day 20. Four jobs remain (due day; days of work left): A (30; 4), B (26; 8), C (32; 6), D (25; 3). Sequencing by critical ratio, lowest first, what is the order?","options":["D–B–A–C","D–A–C–B","B–D–C–A","B–D–A–C"],"answer":2,"explanation":"CR = (due − today) ÷ work left: A 10/4 = 2.5, B 6/8 = 0.75, C 12/6 = 2.0, D 5/3 ≈ 1.67. Ascending: B–D–C–A. EDD would give D–B–A–C and SPT D–A–C–B. B is already behind (CR < 1) despite not being due first.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-220","question":"Three markets with annual loads: M1 at (2, 8) with 300, M2 at (6, 2) with 200 and M3 at (9, 6) with 500. Distances are rectilinear. Site X is at (5, 5) and site Y at (7, 6). Which site has the lower total load × distance, and by how much?","options":["X, by 1,000","Y, by 527","Y, by 600","Y, by 1,000"],"answer":3,"explanation":"X: 300 × (3 + 3) + 200 × (1 + 3) + 500 × (4 + 1) = 1,800 + 800 + 2,500 = 5,100. Y: 300 × (5 + 2) + 200 × (1 + 4) + 500 × (2 + 0) = 2,100 + 1,000 + 1,000 = 4,100. Y wins by 1,000. Straight-line distances would give a gap of about 527 instead.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-221","question":"For jobs waiting at a single machine, all available at the start, which sequencing rule minimises the average flow time (and the average number of jobs in the system)?","options":["Earliest due date (EDD)","First come, first served (FCFS)","Shortest processing time (SPT)","Longest processing time (LPT)"],"answer":2,"explanation":"Putting short jobs first reduces the waiting added to every later job, so SPT minimises mean flow time on a single machine. EDD instead minimises maximum lateness; the makespan is the same for every order.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-222","question":"Which statements about aggregate planning strategies are correct?\nI. A chase strategy keeps finished-goods inventory low.\nII. A level strategy suits firms whose hiring and layoff costs are high.\nIII. A chase strategy suits work that needs highly skilled, hard-to-hire staff.\nIV. A level strategy builds inventory in slack periods to cover peak demand.","options":["I, II and IV only","I and III only","II, III and IV only","All four"],"answer":0,"explanation":"Chase changes output (often the workforce) to match demand, so little stock is built (I). Level keeps output steady, building stock in slack periods (IV), which pays when changing the workforce is costly (II). Hiring and firing skilled staff each period is exactly what a chase plan does badly, so III is false.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-223","question":"Markets with annual loads: M1 at (2, 8) with 300, M2 at (6, 2) with 150 and M3 at (9, 6) with 550. Distances are rectilinear. What location minimises total load × distance, and what is that minimum?","options":["(6.45, 6); 4,005","(6, 6); 4,050","(9, 8); 4,550","(9, 6); 3,750"],"answer":3,"explanation":"With rectilinear distance, use the weighted median on each axis (half the load = 500). X sorted: 2 (300), 6 (cumulative 450), 9 (1,000) → median x = 9. Y sorted: 2 (150), 6 (cumulative 700) → median y = 6. Cost at (9, 6) = 300 × (7 + 2) + 150 × (3 + 4) + 0 = 2,700 + 1,050 = 3,750. The centre of gravity (6.45, 6) costs 4,005 — it is not the rectilinear optimum.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-224","question":"Twenty units are tested for 1,000 hours each; any unit that fails is replaced at once, so the test covers 20,000 unit-hours. Four failures occur. What are the failure rate and the MTBF?","options":["0.2 per hour; 5 hours","0.0002 per hour; 5,000 hours","0.004 per hour; 250 hours","0.0002 per hour; 250 hours"],"answer":1,"explanation":"Failure rate = failures ÷ unit-hours = 4 ÷ 20,000 = 0.0002 per hour. MTBF = 1 ÷ failure rate = 5,000 hours. Dividing by 1,000 hours instead of unit-hours gives 0.004 per hour.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-225","question":"The first unit of a new aircraft sub-assembly took 100 labour hours. The work follows an 80% unit learning curve. How long should the 8th unit take?","options":["64 hours","51.2 hours","40.96 hours","80 hours"],"answer":1,"explanation":"Each doubling of cumulative output multiplies unit time by 0.8. Unit 8 is three doublings from unit 1: 100 × 0.8³ = 51.2 hours. 64 hours is unit 4 and 40.96 hours is unit 16.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-226","question":"Unit 1 of a custom machine took 200 hours, and production follows an 85% unit learning curve. Approximately how many hours will unit 10 take? (Use Tₙ = T₁ × n^b with b = log 0.85 ÷ log 2.)","options":["104.4 hours","122.8 hours","170.0 hours","116.6 hours"],"answer":3,"explanation":"b = log 0.85 ÷ log 2 ≈ -0.2345. T₁₀ = 200 × 10^(-0.2345) ≈ 200 × 0.5828 ≈ 116.6 hours. 122.8 is unit 8 (three doublings) and 104.4 is unit 16 (four doublings); 170 applies the 85% only once.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-227","question":"A contractor's first unit took 50 hours and work follows a 90% unit learning curve (Tₙ = T₁ × n^b, b = log 0.9 ÷ log 2 ≈ −0.152). Four units are already built. Labour costs ₹400 an hour. What is the labour cost of the next four units (units 5 to 8), to the nearest hundred rupees?","options":["≈ ₹60,400","≈ ₹58,300","≈ ₹71,100","₹80,000"],"answer":0,"explanation":"Unit times: T₅ ≈ 39.15, T₆ ≈ 38.08, T₇ ≈ 37.2, T₈ = 50 × 0.9³ = 36.45 hours. Sum ≈ 150.88 hours × ₹400 ≈ ₹60,400. Using T₈ for all four units understates it (≈ ₹58,300); units 1–4 cost about ₹71,100; ₹80,000 ignores learning altogether.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-228","question":"On a learning-curve job, the 4th unit took 72 hours and the 16th unit took 46.08 hours. What is the learning rate?","options":["64%","90%","80%","85%"],"answer":2,"explanation":"From unit 4 to unit 16 there are two doublings (4 → 8 → 16). So rate² = 46.08 ÷ 72 = 0.64, and rate = 0.8, i.e. 80%. Taking 0.64 itself as the rate forgets that two doublings occurred.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-229","question":"A cooling system has a controller (reliability 0.98) in series with a pair of identical pumps in parallel, each with reliability 0.90; the system works if the controller and at least one pump work. What is the system reliability?","options":["0.7938","0.8820","0.9900","0.9702"],"answer":3,"explanation":"Pump pair = 1 − (0.10 × 0.10) = 0.99. System = 0.98 × 0.99 = 0.9702. Treating everything as series gives 0.98 × 0.9 × 0.9 = 0.7938; one pump only gives 0.882; 0.99 forgets the controller.","difficulty":"easy","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-230","question":"A packing line has three stages in series: a feeder (reliability 0.95), a sealing stage with two identical sealers in parallel (each 0.80, either one suffices), and a labeller (0.90). What is the line's reliability, and what would it be without the backup sealer?","options":["0.9120 with backup; 0.684 without","0.8208 with backup; 0.760 without","0.8208 with backup; 0.684 without","0.8550 with backup; 0.684 without"],"answer":2,"explanation":"Sealer pair = 1 − 0.2² = 0.96. Line = 0.95 × 0.96 × 0.90 = 0.8208. Without the backup: 0.95 × 0.80 × 0.90 = 0.684. 0.912 leaves out the labeller; 0.855 drops the sealing stage entirely.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-231","question":"A critical sensor has reliability 0.85. Identical sensors can be installed in parallel (the stage works if at least one works). What is the smallest number of sensors needed for the stage reliability to reach at least 0.999?","options":["3","4","5","7"],"answer":1,"explanation":"Stage reliability = 1 − 0.15ⁿ. n = 3: 1 − 0.003375 = 0.996625 (short). n = 4: 1 − 0.00050625 ≈ 0.99949 ≥ 0.999. So 4 sensors. Thinking each extra unit adds a fixed amount of reliability leads to much larger answers like 7.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-232","question":"A buyer uses a single sampling plan: inspect n = 20 items from each lot and accept the lot if at most c = 1 is defective. If a lot is 5% defective, what is the probability it is accepted (binomial)?","options":["0.736","0.358","0.377","0.264"],"answer":0,"explanation":"P(accept) = P(0) + P(1) = 0.95²⁰ + 20 × 0.05 × 0.95¹⁹ = 0.3585 + 0.3774 ≈ 0.736. 0.358 counts only zero defectives; 0.264 is the rejection probability.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-233","question":"Lots of N = 1,000 are checked with the plan n = 20, c = 1. Rejected lots are screened 100% and all defectives replaced; in accepted lots only the sampled defectives are replaced. If incoming quality is 5% defective, what is the average outgoing quality (AOQ)?","options":["≈ 3.61%","≈ 3.68%","5.00%","≈ 1.32%"],"answer":0,"explanation":"P(accept) ≈ 0.7358. AOQ = p × Pa × (N − n) ÷ N = 0.05 × 0.7358 × 980 ÷ 1,000 ≈ 3.61%. Dropping the (N − n)/N factor gives 3.68%; using the rejection probability gives 1.32%. Rejected lots leave defect-free, which is why AOQ is below 5%.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-234","question":"Match each acceptance-sampling term with its meaning.\n1. AQL  2. LTPD  3. Producer's risk (α)  4. Consumer's risk (β)\na. Probability of accepting a lot whose quality is as bad as the LTPD\nb. Worst average defect level the buyer still regards as satisfactory\nc. Probability of rejecting a lot whose quality is at the AQL\nd. Defect level at which the buyer regards a lot as bad","options":["1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-c, 2-a, 3-b, 4-d"],"answer":1,"explanation":"AQL is the acceptable quality level (good lots); LTPD is the lot tolerance percent defective (bad lots). Producer's risk is rejecting a good (AQL) lot; consumer's risk is accepting a bad (LTPD) lot. Swapping the two risks is the classic mistake.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-235","question":"A sampling plan inspects n = 50 items and accepts the lot if c ≤ 2 defectives are found. Using the Poisson approximation, what is the probability of accepting a lot that is 2% defective?","options":["0.736","0.632","0.920","0.981"],"answer":2,"explanation":"np = 50 × 0.02 = 1. P(≤ 2) = e⁻¹ (1 + 1 + 1/2) = 2.5 × 0.3679 ≈ 0.92. 0.736 stops at one defective; 0.632 is 1 − e⁻¹; 0.981 wrongly includes 3 defectives.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-236","question":"Over 40 replenishment cycles a store ran out of an item in 5 cycles. Customers asked for 4,500 units in total, of which 4,230 were supplied immediately from stock. What are the cycle-service level and the fill rate?","options":["Cycle-service level 94%; fill rate 87.5%","Cycle-service level 87.5%; fill rate 87.5%","Cycle-service level 12.5%; fill rate 6%","Cycle-service level 87.5%; fill rate 94%"],"answer":3,"explanation":"Cycle-service level = cycles without a stockout ÷ cycles = 35 ÷ 40 = 87.5%. Fill rate = demand met from stock ÷ total demand = 4,230 ÷ 4,500 = 94%. Fill rate is usually higher, because a stockout cycle still fills most of its demand.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-237","question":"An item is ordered 500 units at a time. Lead-time demand is normal with σ = 40 units, and the firm holds safety stock of 40 units (z = 1). For z = 1, the cumulative normal probability is 0.8413 and the standard loss function L(z) = 0.0833. What are the cycle-service level and the fill rate?","options":["CSL 99.3%; fill rate 84.1%","CSL 84.1%; fill rate 84.1%","CSL 84.1%; fill rate 99.3%","CSL 84.1%; fill rate 91.7%"],"answer":2,"explanation":"CSL = P(lead-time demand ≤ ROP) = 84.1%. Expected shortage per cycle = L(z) × σ = 0.0833 × 40 ≈ 3.33 units. Fill rate = 1 − 3.33 ÷ 500 ≈ 99.3%. 91.7% wrongly uses 1 − L(z). A modest CSL can still give a very high fill rate when the order quantity is large.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-238","question":"An importer buys a part at US$12 FOB. Take ₹83 per dollar. Freight is ₹40 per unit, insurance is 1% of the FOB value, customs duty is 10% of the CIF value, and clearing and handling cost ₹8 per unit. What is the landed cost per unit?","options":["₹1,158.56","₹1,153.56","₹1,147.60","₹1,053.96"],"answer":0,"explanation":"FOB = 12 × 83 = ₹996. Insurance = ₹9.96. CIF = 996 + 40 + 9.96 = ₹1045.96. Duty = 10% of CIF = ₹104.596. Landed = 1045.96 + 104.596 + 8 ≈ ₹1158.56. Charging duty on FOB only gives ₹1153.56; leaving out insurance gives ₹1147.60; skipping duty gives ₹1053.96.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-239","question":"A firm needs 10,000 units of a component a year. A supplier quotes ₹85 per unit. Making it costs, per unit: materials ₹40, direct labour ₹20, variable overhead ₹10 and allocated fixed overhead ₹25. If the part is bought, 60% of that fixed overhead will continue anyway. Should the firm make or buy, and what is the annual saving from the better option?","options":["Buy; saves ₹1,00,000","Make; saves ₹1,50,000","Buy; saves ₹50,000","Make; saves ₹50,000"],"answer":3,"explanation":"Relevant make cost = variable ₹70 + avoidable fixed (40% of ₹25 = ₹10) = ₹80 per unit, versus ₹85 to buy. Making saves ₹5 × 10,000 = ₹50,000. Using the full ₹95 cost wrongly favours buying (₹1,00,000); ignoring the avoidable fixed cost overstates the saving (₹1,50,000).","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-240","question":"A firm needs 10,000 units of a component a year. A supplier quotes ₹85 per unit. Making it costs, per unit: materials ₹40, direct labour ₹20, variable overhead ₹10 and allocated fixed overhead ₹25. If the part is bought, 60% of that fixed overhead will continue anyway. If the part is bought, the freed capacity can make another product earning a contribution of ₹2,00,000 a year. What should the firm do now, and what is the annual advantage?","options":["Make; saves ₹50,000","Buy; saves ₹1,50,000","Buy; saves ₹2,00,000","Buy; saves ₹3,00,000"],"answer":1,"explanation":"Making costs ₹80 × 10,000 = ₹8,00,000 in relevant cost plus ₹2,00,000 of lost contribution (opportunity cost) = ₹10,00,000. Buying costs ₹8,50,000. Buying is better by ₹1,50,000. Ignoring the opportunity cost keeps the old 'make' answer; using the full ₹95 cost as well inflates the gap to ₹3,00,000.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-241","question":"Making a part needs new equipment with fixed cost ₹6 lakh a year plus ₹45 variable cost per unit. Buying it costs ₹60 per unit. At what annual volume are the two options equally costly?","options":["13,333 units","40,000 units","10,000 units","24,000 units"],"answer":1,"explanation":"Indifference: 6,00,000 + 45Q = 60Q → Q = 6,00,000 ÷ 15 = 40,000. Above it, making is cheaper. Dividing by 45 or 60 instead of the ₹15 difference gives 13,333 or 10,000.","difficulty":"easy","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-242","question":"A firm compares one national warehouse with two regional ones (₹ lakh a year). One warehouse: fixed cost 40, outbound freight 90, inbound freight 20, inventory carrying cost 60. Two warehouses: fixed cost 40 each, outbound freight 55, inbound freight 26; inventory carrying cost follows the square-root law. Which option is cheaper and by about how much?","options":["One warehouse, by ₹11 lakh","Two warehouses, by ₹4.15 lakh","One warehouse, by ₹71 lakh","One warehouse, by ₹35.85 lakh"],"answer":3,"explanation":"Square-root law: inventory with 2 sites = 60 × √2 ≈ ₹84.85 lakh. One site: 40 + 90 + 20 + 60 = ₹210 lakh. Two sites: 80 + 55 + 26 + 84.85 ≈ ₹245.85 lakh. One warehouse is cheaper by ≈ ₹35.85 lakh. Keeping inventory at 60 gives a gap of 11; doubling it gives 71; counting only one fixed cost makes two sites look cheaper.","difficulty":"hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-243","question":"Each shipment carries goods worth ₹1 crore, and the firm's inventory carrying cost is 20% a year (365 days). Options per shipment — rail: freight ₹60,000, 12 days in transit; road: ₹85,000, 5 days; air: ₹2,40,000, 1 day. Counting freight plus in-transit carrying cost, which mode is cheapest and about what does it cost per shipment?","options":["Road, ≈ ₹1,12,397","Rail, ₹60,000","Rail, ≈ ₹1,25,753","Air, ≈ ₹2,45,479"],"answer":0,"explanation":"In-transit cost = 1 crore × 20% × days ÷ 365 = ₹5,479 a day. Rail = 60,000 + 12 × 5,479 ≈ ₹1,25,753; road = 85,000 + 5 × 5,479 ≈ ₹1,12,397; air = 2,40,000 + 5,479 ≈ ₹2,45,479. Road wins. Looking at freight alone wrongly picks rail.","difficulty":"hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-244","question":"A firm can open distribution centre A (fixed cost ₹4,000 a week), B (₹5,000) or both; each has ample capacity. Weekly demand: M1 400 units, M2 300, M3 300. Shipping cost per unit from A: ₹10, ₹14, ₹20 to M1, M2, M3; from B: ₹18, ₹12, ₹9. Each market is served from the cheapest open centre. Which configuration minimises total weekly cost, and what is that cost?","options":["Open B only; ₹18,500","Open both; ₹19,300","Open A only; ₹18,200","Open both; ₹10,300"],"answer":2,"explanation":"A only: 4,000 + 4,000 + 4,200 + 6,000 = ₹18,200. B only: 5,000 + 7,200 + 3,600 + 2,700 = ₹18,500. Both: 9,000 + 4,000 (M1 from A) + 3,600 + 2,700 (M2, M3 from B) = ₹19,300. Both has the lowest freight (₹10,300) but the second fixed cost outweighs the saving.","difficulty":"very-hard","source":"Consulting · Business analyst · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-245","question":"Daily demand for a spare part is 0, 1, 2 or 3 units with probabilities 0.10, 0.30, 0.40 and 0.20. Random numbers 00–99 are assigned in that order, starting at 00 (so 0 units = 00–09, and so on). Using the random numbers 10, 87, 40, 06, 79, 59, 92, 39 for eight days, what is the total simulated demand?","options":["12 units","13.6 units","16 units","14 units"],"answer":3,"explanation":"Ranges: 0 → 00–09, 1 → 10–39, 2 → 40–79, 3 → 80–99. The numbers give 1, 3, 2, 0, 2, 2, 3, 1 = 14. Starting the ranges at 01 shifts the boundary numbers 10 and 40 and gives 12; 13.6 is the expected value (1.7 × 8), not the simulated result.","difficulty":"moderate","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-246","question":"A one-person counter is simulated for six customers. Inter-arrival time: 1 min (RN 00–19), 2 min (20–69), 3 min (70–99). Service time: 1 min (00–29), 2 min (30–69), 3 min (70–99). The clock starts at 0 with the counter empty, and the first customer arrives after the first inter-arrival time. Inter-arrival RNs: 45, 12, 78, 05, 33, 91. Service RNs: 81, 50, 22, 73, 64, 10. What are the total customer waiting time and the counter's idle time until the last customer leaves?","options":["Waiting 5 min; idle 2 min","Waiting 7 min; idle 0 min","Waiting 7 min; idle 2 min","Waiting 9 min; idle 3 min"],"answer":2,"explanation":"Inter-arrivals 2, 1, 3, 1, 2, 3 → arrivals at 2, 3, 6, 7, 9, 12. Services 3, 2, 1, 3, 2, 1. Starts/ends: C1 2–5; C2 5–7 (waits 2); C3 7–8 (1); C4 8–11 (1); C5 11–13 (2); C6 13–14 (1). Total wait = 7 min. The counter is idle only from 0 to 2, so 2 min, and the last customer leaves at 14.","difficulty":"very-hard","source":"Ops MT · Supply chain · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-247","question":"Each month 80% of brand A's buyers stay with A and 20% switch to B; 70% of B's buyers stay and 30% switch to A. Today each brand has 50% of the market. What will A's share be two months from now?","options":["55%","57.5%","60%","65%"],"answer":1,"explanation":"Month 1: A = 0.5 × 0.8 + 0.5 × 0.3 = 55%. Month 2: A = 0.55 × 0.8 + 0.45 × 0.3 = 0.44 + 0.135 = 57.5%. 55% is only one month ahead; 60% is the long-run share, 0.3 ÷ (0.2 + 0.3).","difficulty":"moderate","source":"Business analyst · KPO · MBA placement pattern"},
  {"id":"mgmt-operations-analytics-248","question":"Monthly switching among three brands (rows = this month's brand, columns = next month's): X → X 0.7, Y 0.2, Z 0.1; Y → X 0.1, Y 0.8, Z 0.1; Z → X 0.2, Y 0.2, Z 0.6. Current shares are X 40%, Y 35%, Z 25%. What are the long-run (steady-state) shares?","options":["X 30%, Y 50%, Z 20%","X 36.5%, Y 41%, Z 22.5%","X 40%, Y 35%, Z 25%","X 33.3%, Y 33.3%, Z 33.3%"],"answer":0,"explanation":"Solve π = πP with shares summing to 1: X = 0.7X + 0.1Y + 0.2Z and Z = 0.1X + 0.1Y + 0.6Z. These give X = 30%, Y = 50%, Z = 20% (the X equation gives Y = 5X/3, the Z equation gives Z = (X + Y)/4 = 2X/3, so X × 10/3 = 1). The first set of wrong figures is just next month's shares; steady state does not depend on today's shares.","difficulty":"very-hard","source":"Business analyst · KPO · MBA placement pattern"}
];

export default questions;
